 function reportNavHtml(){let tabs=[['overview','Visão Geral'],['clients','Clientes'],['retention','Retenção'],['agenda','Agenda'],['pros','Profissionais'],['services','Serviços'],['stock','Estoque'],['finance','Financeiro'],['marketing','Marketing'],['audit','Auditoria']];return `<div class="report-nav">${tabs.map(([id,n])=>`<button class="${reportsTab===id?'active ':''}${['overview','clients','retention'].includes(id)?'':'locked'}" onclick="setReportsTab('${id}')">${n}${['overview','clients','retention'].includes(id)?'':' · em breve'}</button>`).join('')}</div>`}
 function reportKpi(title,value,sub,delta='',type=''){return `<div class="report-kpi ${type?'clickable':''}" ${type?`onclick="openReportDrilldown('${type}')"`:''}><span>${title}</span><b>${value}</b><small>${sub}</small>${delta}</div>`}
 function reportTopRows(map,formatter,limit=8){let arr=[...map.entries()].map(([id,v])=>({id,v,client:reportClient(id)})).filter(x=>x.client).sort((a,b)=>b.v-a.v).slice(0,limit),max=Math.max(1,...arr.map(x=>x.v));return arr.length?`<div class="report-rank">${arr.map(x=>`<div class="report-rank-row"><div class="report-rank-name">${escapeHtml(x.client.name)}</div><div class="report-bar"><i style="width:${Math.max(3,x.v/max*100)}%"></i></div><div class="report-rank-value">${formatter(x.v)}</div></div>`).join('')}</div>`:'<div class="report-empty">Sem dados no período.</div>'}
 function reportDistribution(field,metrics){let counts=new Map();metrics.clientIds.forEach(id=>{let c=reportClient(id),k=String(c?.[field]||'Não informado');counts.set(k,(counts.get(k)||0)+1)});let max=Math.max(1,...counts.values());return counts.size?`<div class="report-rank">${[...counts.entries()].sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="report-rank-row"><div class="report-rank-name">${escapeHtml(k)}</div><div class="report-bar"><i style="width:${v/max*100}%"></i></div><div class="report-rank-value">${v}</div></div>`).join('')}</div>`:'<div class="report-empty">Sem dados no período.</div>'}

 function renderReportOverview(s){let c=s.current,p=s.previous;return `<div class="report-overview-hero"><div class="report-overview-panel"><h2>Clientes & Retenção</h2><p>Primeira fase dos Relatórios Gerenciais. Os atendimentos usam fatos operacionais concluídos; o faturamento vem das comandas pagas pela mesma regra comercial utilizada na DRE, incluindo combos, Modelo/Parceria e Conta Mensal sem reconhecer receita novamente no recebimento.</p><span class="report-period-chip">${formatDateBR(c.f.from)} → ${formatDateBR(c.f.to)}</span></div><div class="report-card"><h3>Critério de inatividade</h3><div class="sub">Parâmetro gerencial separado do prazo de retorno dos serviços.</div><div class="report-settings-inline">Inativa após <input id="repInactiveDays" type="number" min="1" value="${Number(db.reportSettings.inactiveDays||90)}"> dias <button class="btn btn-ghost btn-sm" onclick="reportSetInactiveDays()">Salvar</button></div><div class="report-definition">Prazos de retorno nunca usam este valor: eles vêm exclusivamente do cadastro do serviço.</div></div></div>
 <div class="report-kpis">${reportKpi('Clientes atendidas',c.clientIds.length,'Clientes únicas com atendimento concluído.',reportDelta(c.clientIds.length,p.clientIds.length),'clients_total')}${reportKpi('Faturamento',money(c.revenue),'Receita reconhecida pelas comandas no período.',reportDelta(c.revenue,p.revenue),'revenue')}${reportKpi('Taxa de retorno',reportPctText(c.returnRate),'Clientes do período que já tinham visita anterior.',reportDelta(c.returnRate,p.returnRate,true),'return_rate')}${reportKpi('Retenção no salão',reportPctText(c.salonRetention),'Coorte: clientes do período anterior que voltaram no atual.',reportDelta(c.salonRetention,p.salonRetention,true),'salon_retention')}</div>
 <div class="report-grid-2"><div class="report-card"><h3>Clientes com maior faturamento</h3><div class="sub">Receita atribuída ao período e aos filtros selecionados.</div>${reportTopRows(c.revenueBy,money)}</div><div class="report-card"><h3>Reativação prioritária</h3><div class="sub">Somente clientes cujo serviço possui prazo de retorno definido e já venceu.</div>${c.reactivation.length?`<div class="report-table-wrap"><table class="report-table"><thead><tr><th>Cliente</th><th>Atraso</th><th>Serviço</th></tr></thead><tbody>${c.reactivation.slice(0,8).map(r=>`<tr class="clickable" onclick="openReportDrilldown('reactivation')"><td>${escapeHtml(r.client?.name||'—')}</td><td><span class="report-badge bad">${r.daysLate} dias</span></td><td>${escapeHtml(r.service)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="report-empty">Nenhuma cliente atrasada pelos prazos cadastrados.</div>'}</div></div>`}

 function renderReportClients(s){let c=s.current,p=s.previous;return `<div class="report-section-head"><div><h2>Clientes</h2><div class="muted">Base real de atendimentos concluídos e faturamento reconhecido.</div></div><div class="spacer"></div><div class="report-settings-inline">Inativa após <input id="repInactiveDays" type="number" min="1" value="${Number(db.reportSettings.inactiveDays||90)}"> dias <button class="btn btn-ghost btn-sm" onclick="reportSetInactiveDays()">Aplicar</button></div></div>
 <div class="report-kpis">${reportKpi('Clientes atendidas',c.clientIds.length,'Clientes únicas no período.',reportDelta(c.clientIds.length,p.clientIds.length),'clients_total')}${reportKpi('Clientes novas',c.newIds.length,'Primeira visita ao salão ocorreu no período.',reportDelta(c.newIds.length,p.newIds.length),'clients_new')}${reportKpi('Clientes recorrentes',c.recurringIds.length,'Já possuíam atendimento anterior.',reportDelta(c.recurringIds.length,p.recurringIds.length),'clients_recurring')}${reportKpi('Faturamento',money(c.revenue),'Mesma lógica comercial da DRE.',reportDelta(c.revenue,p.revenue),'revenue')}${reportKpi('Ticket médio',money(c.ticket),'Faturamento ÷ atendimentos com comanda financeira.',reportDelta(c.ticket,p.ticket),'ticket')}${reportKpi('Frequência média',reportNumber(c.frequency,2),'Atendimentos concluídos ÷ clientes únicas.',reportDelta(c.frequency,p.frequency),'frequency')}${reportKpi('Clientes inativas',c.inactive.length,`Sem visita há ${Number(db.reportSettings.inactiveDays||90)}+ dias até o fim do período.`,reportDelta(c.inactive.length,p.inactive.length),'inactive')}${reportKpi('Faltas / cancelamentos',`${c.missed.length} / ${c.cancelled.length}`,'Eventos da Agenda; não entram como atendimento.',reportDelta(c.missed.length+c.cancelled.length,p.missed.length+p.cancelled.length),'agenda_losses')}</div>
 <div class="report-grid-2"><div class="report-card"><h3>Maior faturamento por cliente</h3><div class="sub">Combos e Modelo/Parceria seguem a alocação comercial já estabilizada.</div>${reportTopRows(c.revenueBy,money,10)}</div><div class="report-card"><h3>Maior frequência</h3><div class="sub">Uma comanda/visita conta como um atendimento, mesmo com múltiplos serviços.</div>${reportTopRows(c.frequencyBy,v=>`${v} atendimento${v===1?'':'s'}`,10)}</div><div class="report-card"><h3>Origem do cadastro</h3><div class="sub">Campo operacional de onde o cadastro entrou.</div>${reportDistribution('origin',c)}</div><div class="report-card"><h3>Como conheceu o Império</h3><div class="sub">Fonte comercial/marketing separada da origem do cadastro.</div>${reportDistribution('source',c)}</div></div>
 <div class="report-card"><h3>Qualidade da base</h3><div class="report-note"><b>Clientes novas x recorrentes:</b> usa a primeira visita concluída registrada no histórico consolidado. <b>Faturamento:</b> somente comandas pagas/fechadas, inclusive Conta Mensal na data do atendimento; o recebimento posterior não gera receita novamente. Atendimentos históricos sem comanda podem contar para frequência e retenção, mas não inventam faturamento.</div></div>`}

 function reportRetentionTable(rows,title){return `<div class="report-card"><h3>${title}</h3><div class="sub">Base = oportunidades com prazo de retorno cadastrado no serviço.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Grupo</th><th class="num">Base</th><th class="num">Retornaram</th><th class="num">Taxa</th><th class="num">No prazo*</th></tr></thead><tbody>${rows.length?rows.slice(0,12).map(x=>`<tr><td>${escapeHtml(x.label)}</td><td class="num">${x.base}</td><td class="num">${x.returned}</td><td class="num">${reportPctText(x.returnRate)}</td><td class="num">${x.mature?reportPctText(x.onTimeRate):'—'}</td></tr>`).join(''):'<tr><td colspan="5" class="muted">Sem base com prazo definido.</td></tr>'}</tbody></table></div></div>`}
 function renderReportRetention(s){let c=s.current,p=s.previous;return `<div class="report-section-head"><div><h2>Retenção</h2><div class="muted">Retorno calculado sem criar prazos artificiais.</div></div></div>
 <div class="report-kpis">${reportKpi('Taxa de retorno',reportPctText(c.returnRate),'Clientes atendidas que já tinham visita anterior.',reportDelta(c.returnRate,p.returnRate,true),'return_rate')}${reportKpi('Retenção no salão',reportPctText(c.salonRetention),'Clientes do período anterior que reapareceram no período atual.',reportDelta(c.salonRetention,p.salonRetention,true),'salon_retention')}${reportKpi('Mesma profissional',reportPctText(c.sameProRetention),'Entre as clientes retidas da coorte, quantas repetiram ao menos uma profissional.',reportDelta(c.sameProRetention,p.sameProRetention,true),'same_pro')}${reportKpi('Retorno no prazo',reportPctText(c.onTimeRate),'Entre oportunidades já maduras, retornos até o prazo do serviço.',reportDelta(c.onTimeRate,p.onTimeRate,true),'on_time')}${reportKpi('Atrasadas para retorno',c.overdue.length,'Prazo definido venceu e não houve nova visita até o fim do período.',reportDelta(c.overdue.length,p.overdue.length),'overdue')}${reportKpi('Não retornaram',c.noReturn.length,'Oportunidades sem visita posterior; inclui as ainda não vencidas.',reportDelta(c.noReturn.length,p.noReturn.length),'no_return')}${reportKpi('Intervalo médio',c.avgInterval?`${reportNumber(c.avgInterval,1)} dias`:'—','Intervalo entre visitas concluídas das recorrentes do período.',reportDelta(c.avgInterval,p.avgInterval),'avg_interval')}${reportKpi('Para reativação',c.reactivation.length,'Lista acionável: último serviço com prazo definido já vencido.',reportDelta(c.reactivation.length,p.reactivation.length),'reactivation')}</div>
 <div class="report-card"><div class="report-section-head"><div><h3>Clientes para reativação</h3><div class="sub">A data de referência é o fim do período selecionado. Serviços sem prazo configurado não entram como atrasados.</div></div></div>${reportReactivationTable(c.reactivation)}</div>
 <div class="report-grid-2">${reportRetentionTable(c.groups.service,'Retorno por serviço')}${reportRetentionTable(c.groups.category,'Retorno por categoria')}${reportRetentionTable(c.groups.professional,'Retorno por profissional')}${reportRetentionTable(c.groups.unit,'Retorno por unidade')}</div>
 <div class="report-note"><b>* No prazo:</b> considera somente oportunidades maduras — aquelas que já retornaram ou cujo prazo configurado já venceu até ${formatDateBR(c.f.to)}. Quando o serviço não possui prazo de retorno, o sistema exibe “Sem prazo definido” e não classifica a cliente como atrasada.</div>`}

 function reportReactivationTable(rows){return `<div class="report-table-wrap"><table class="report-table report-reactivation"><thead><tr><th>Cliente</th><th>Telefone</th><th>Último atendimento</th><th>Serviço</th><th>Profissional</th><th>Dias desde visita</th><th>Prazo esperado</th><th>Dias de atraso</th><th>Unidade</th><th></th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td><b>${escapeHtml(r.client?.name||'—')}</b></td><td>${escapeHtml(r.client?.phone||'—')}</td><td>${formatDateBR(r.visit.date)}</td><td>${escapeHtml(r.service)}</td><td>${escapeHtml(r.professional||'—')}</td><td>${r.daysSince}</td><td>${r.returnDays} dias · ${formatDateBR(r.dueDate)}</td><td><span class="report-badge bad">${r.daysLate}</span></td><td>${escapeHtml(reportUnitName(r.unitId))}</td><td><div class="report-actions"><button class="btn btn-ghost btn-sm" onclick="closeModal();openClient('${r.clientId}')">Abrir</button><button class="btn btn-soft btn-sm" onclick="reportCopyReactivation('${r.clientId}')">Copiar WhatsApp</button></div></td></tr>`).join(''):'<tr><td colspan="10"><div class="report-empty">Nenhuma cliente atrasada pelos prazos de retorno cadastrados.</div></td></tr>'}</tbody></table></div>`}
 function reportCopyReactivation(clientId){let s=window.v50ReportCache||reportBuildState(),r=s.current.reactivation.find(x=>x.clientId===clientId),c=reportClient(clientId);if(!r||!c)return;let first=String(c.name||'').trim().split(/\s+/)[0]||'cliente',text=`Olá, ${first}! Tudo bem? Sentimos sua falta no Império das Unhas 💜 Seu retorno de ${r.service} estava previsto para ${formatDateBR(r.dueDate)}. Se quiser, podemos te ajudar a encontrar um horário.`;copyTextSafe(text);toast('Mensagem copiada para o WhatsApp ✓')}
 window.reportCopyReactivation=reportCopyReactivation;

 function renderReportComing(tab){let names={agenda:'Agenda',pros:'Profissionais',services:'Serviços',stock:'Estoque',finance:'Financeiro',marketing:'Marketing',audit:'Auditoria'};return `<div class="report-coming"><b>${names[tab]||'Relatório'} · estrutura preparada</b><div class="muted">Esta navegação já faz parte do módulo de Relatórios. A implementação completa ficará para a próxima fase para não misturar regras novas com a estabilização de Clientes e Retenção.</div></div>`}

 function renderReports(){
  subbar.textContent='Relatórios gerenciais · dados reais · comparação · drill-down';let s=reportBuildState();window.v50ReportCache=s;
  let content=reportsTab==='overview'?renderReportOverview(s):reportsTab==='clients'?renderReportClients(s):reportsTab==='retention'?renderReportRetention(s):renderReportComing(reportsTab);
  adminPage.innerHTML=`<div class="page-head"><div><h1>Relatórios</h1><div class="muted">Indicadores rastreáveis a partir das operações do sistema</div></div><div class="spacer"></div><span class="pill">V50 · Clientes + Retenção</span></div><div class="report-shell">${reportNavHtml()}${reportFilterHtml()}${content}</div>`
 }
 window.renderReports=renderReports;
 const _renderAdminV50Base=renderAdmin;
 renderAdmin=function(){if(page==='reports')return renderReports();return _renderAdminV50Base()};

 function reportClientRows(ids,metrics){return ids.map(id=>{let c=reportClient(id),vis=metrics.visits.filter(v=>v.clientId===id),rev=metrics.revenueBy.get(id)||0,last=vis.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];return {cells:[`<b>${escapeHtml(c?.name||'—')}</b>`,escapeHtml(c?.phone||'—'),String(vis.length),money(rev),last?formatDateBR(last.date):'—',escapeHtml(c?.origin||'—'),escapeHtml(c?.source||'—')],clientId:id}})}
 function reportBookingRows(arr){return arr.map(b=>({cells:[`<b>${escapeHtml(reportClient(b.clientId)?.name||b.client||'—')}</b>`,formatDateBR(b.date),escapeHtml(reportUnitName(b.unit)),escapeHtml((b.items||[]).map(i=>i.service).join(' + ')||'—'),escapeHtml((b.items||[]).map(i=>reportProName(i.pro)).join(', ')||'—'),escapeHtml(b.status)]}))}
 function reportDrillTable(headers,rows,{clientAction=false}={}){return `<div class="report-table-wrap"><table class="report-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}${clientAction?'<th></th>':''}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.cells.map(c=>`<td>${c}</td>`).join('')}${clientAction?`<td>${r.clientId?`<button class="btn btn-ghost btn-sm" onclick="closeModal();openClient('${r.clientId}')">Abrir</button>`:''}</td>`:''}</tr>`).join(''):`<tr><td colspan="${headers.length+(clientAction?1:0)}"><div class="report-empty">Nenhum registro para este indicador.</div></td></tr>`}</tbody></table></div>`}
 function openReportDrilldown(type){
  let s=window.v50ReportCache||reportBuildState(),m=s.current,title='Detalhamento',body='';
  if(type==='clients_total'||type==='clients_new'||type==='clients_recurring'){let ids=type==='clients_total'?m.clientIds:type==='clients_new'?m.newIds:m.recurringIds;title=type==='clients_total'?'Clientes atendidas':type==='clients_new'?'Clientes novas':'Clientes recorrentes';body=reportDrillTable(['Cliente','Telefone','Atendimentos','Faturamento','Última no período','Origem','Como conheceu'],reportClientRows(ids,m),{clientAction:true})}
  else if(['revenue','ticket','frequency'].includes(type)){title=type==='revenue'?'Faturamento por cliente':type==='ticket'?'Base do ticket médio':'Frequência por cliente';body=reportDrillTable(['Cliente','Telefone','Atendimentos','Faturamento','Última no período','Origem','Como conheceu'],reportClientRows(m.clientIds,m).sort((a,b)=>0),{clientAction:true})}
  else if(type==='inactive'){title='Clientes inativas';body=reportDrillTable(['Cliente','Telefone','Última visita','Dias sem visita','Unidade'],m.inactive.map(x=>({cells:[`<b>${escapeHtml(x.client?.name||'—')}</b>`,escapeHtml(x.client?.phone||'—'),formatDateBR(x.date),String(x.daysSince),escapeHtml(reportUnitName(x.unitId))],clientId:x.clientId})),{clientAction:true})}
  else if(type==='agenda_losses'){title='Faltas e cancelamentos';body=`<h3 style="margin:0 0 8px">Faltas</h3>${reportDrillTable(['Cliente','Data','Unidade','Serviço','Profissional','Status'],reportBookingRows(m.missed))}<h3 style="margin:18px 0 8px">Cancelamentos</h3>${reportDrillTable(['Cliente','Data','Unidade','Serviço','Profissional','Status'],reportBookingRows(m.cancelled))}`}
  else if(type==='return_rate'){title='Clientes que retornaram';body=reportDrillTable(['Cliente','Telefone','Atendimentos','Faturamento','Última no período','Origem','Como conheceu'],reportClientRows(m.recurringIds,m),{clientAction:true})}
  else if(type==='salon_retention'||type==='same_pro'){let ids=type==='salon_retention'?m.retainedIds:m.sameProIds;title=type==='salon_retention'?'Retenção no salão':'Retenção com a mesma profissional';body=reportDrillTable(['Cliente','Telefone','Atendimentos','Faturamento','Última no período','Origem','Como conheceu'],reportClientRows(ids,m),{clientAction:true})}
  else if(type==='on_time'||type==='overdue'||type==='no_return'){let arr=type==='on_time'?m.onTime:type==='overdue'?m.overdue:m.noReturn;title=type==='on_time'?'Retornos dentro do prazo':type==='overdue'?'Clientes atrasadas para retorno':'Oportunidades sem retorno';body=reportDrillTable(['Cliente','Visita-base','Serviço','Prazo','Vencimento','Próxima visita','Situação'],arr.map(o=>{let c=reportClient(o.visit.clientId),service=o.critical.map(r=>r.serviceName).join(' + '),status=o.state==='ontime'?'No prazo':o.state==='late_return'?`Retornou ${o.daysLate}d após prazo`:o.state==='overdue'?`${o.daysLate}d atrasada`:'Ainda no prazo';return {cells:[`<b>${escapeHtml(c?.name||'—')}</b>`,formatDateBR(o.visit.date),escapeHtml(service),`${o.returnDays} dias`,formatDateBR(o.dueDate),o.nextVisit?formatDateBR(o.nextVisit.date):'—',`<span class="report-badge ${o.state==='ontime'?'good':o.state==='overdue'?'bad':'warn'}">${escapeHtml(status)}</span>`],clientId:o.visit.clientId}}),{clientAction:true})}
  else if(type==='avg_interval'){title='Intervalos entre atendimentos';let rows=[];for(const v of m.visits){let p=reportPreviousVisit(s.data,v.clientId,v.date);if(!p)continue;let c=reportClient(v.clientId);rows.push({cells:[`<b>${escapeHtml(c?.name||'—')}</b>`,formatDateBR(p.date),formatDateBR(v.date),`${reportDaysBetween(p.date,v.date)} dias`,escapeHtml(reportUnitName(v.unitId))],clientId:v.clientId})}body=reportDrillTable(['Cliente','Visita anterior','Visita atual','Intervalo','Unidade'],rows,{clientAction:true})}
  else if(type==='reactivation'){title='Lista de reativação';body=reportReactivationTable(m.reactivation)}
  else return;
  modal(title,body,`<button class="btn btn-primary" onclick="closeModal()">Fechar</button>`)
 }
 window.openReportDrilldown=openReportDrilldown;

/* ===== V51 · Relatórios Gerenciais: aprofundamento Clientes + Retenção ===== */
const V51_SCHEMA=51;
function v51Migrate(){let changed=false;db.reportSettings=db.reportSettings||{};if(!Number(db.reportSettings.returnLateGraceDays)){db.reportSettings.returnLateGraceDays=7;changed=true}let v=Math.max(1,Math.round(Number(db.reportSettings.returnLateGraceDays||7)));if(db.reportSettings.returnLateGraceDays!==v){db.reportSettings.returnLateGraceDays=v;changed=true}if(Number(db.schemaVersion||0)<V51_SCHEMA){db.schemaVersion=V51_SCHEMA;db.schemaMigratedAt=new Date().toISOString();changed=true}if(changed)save({render:false})}
v51Migrate();

function reportVisitFacts(data,visit){return data.serviceFacts.filter(s=>s.visitKey===visit?.key)}
function reportFirstCurrentVisit(visits,clientId){return visits.filter(v=>v.clientId===clientId).slice().sort((a,b)=>(a.date+a.key).localeCompare(b.date+b.key))[0]||null}
function reportLastPeriodVisit(visits,clientId){return visits.filter(v=>v.clientId===clientId).slice().sort((a,b)=>(b.date+b.key).localeCompare(a.date+a.key))[0]||null}
function reportIntersect(a,b){let s=new Set(a||[]);return (b||[]).some(x=>s.has(x))}
function reportUnique(arr){return [...new Set((arr||[]).filter(Boolean))]}
function reportClientHistoricalAverage(data,clientId,f){
  let vs=data.visits.filter(v=>v.clientId===clientId&&v.date<=f.to&&reportVisitMatches(v,f,data));
  let paid=vs.map(v=>reportVisitRevenue(v,f,data)).filter(v=>v>0),total=paid.reduce((a,b)=>a+b,0);
  return {paidVisits:paid.length,total,avg:paid.length?total/paid.length:0}
}
function reportRiskBand(daysLate,daysSince){
  let mild=Math.max(1,Number(db.reportSettings?.returnLateGraceDays||7)),inactive=Math.max(1,Number(db.reportSettings?.inactiveDays||90));
  if(daysLate<=0)return {id:'on_time',label:'No prazo',cls:'good',order:0};
  if(daysSince>=inactive)return {id:'inactive',label:'Inativa',cls:'bad',order:3};
  if(daysLate<=mild)return {id:'mild',label:'Atraso leve',cls:'warn',order:1};
  return {id:'critical',label:'Atraso crítico',cls:'bad',order:2};
}
function reportEnrichReactivation(data,f,rows){
  return (rows||[]).map(r=>{
    let hist=reportClientHistoricalAverage(data,r.clientId,f),potential=hist.avg>0&&r.returnDays>0?hist.avg*(30/r.returnDays):0,band=reportRiskBand(r.daysLate,r.daysSince);
    return {...r,riskBand:band,potentialMonthly:potential,historicalAvgTicket:hist.avg};
  }).sort((a,b)=>(b.riskBand?.order||0)-(a.riskBand?.order||0)||Number(b.potentialMonthly||0)-Number(a.potentialMonthly||0)||b.daysLate-a.daysLate)
}
function reportPortfolio(data,f){
  let latest=reportLatestVisitRows(data,f),rows=[];
  for(const v of latest){
    let facts=data.serviceFacts.filter(s=>s.visitKey===v.key&&reportServiceMatches(s,f));
    let defined=facts.filter(s=>s.returnDefined);
    if(!defined.length){rows.push({clientId:v.clientId,visit:v,state:'undefined',label:'Sem prazo definido',cls:'',daysSince:reportDaysBetween(v.date,f.to)});continue}
    let minDays=Math.min(...defined.map(s=>Number(s.returnDays))),dueDate=addDaysISO(v.date,minDays),daysSince=reportDaysBetween(v.date,f.to),daysLate=reportDaysBetween(dueDate,f.to),band=reportRiskBand(daysLate,daysSince);
    rows.push({clientId:v.clientId,visit:v,state:band.id,label:band.label,cls:band.cls,returnDays:minDays,dueDate,daysSince,daysLate:Math.max(0,daysLate)});
  }
  let count=id=>reportUnique(rows.filter(r=>r.state===id).map(r=>r.clientId)).length;
  return {rows,onTime:count('on_time'),mild:count('mild'),critical:count('critical'),inactive:count('inactive'),undefined:count('undefined')}
}
function reportCohorts(data,f,newIds){
  let months=new Map();
  for(const id of (newIds||[])){
    let first=reportClientHistory(data,id,f.to)[0];if(!first)continue;let month=first.date.slice(0,7),nexts=data.visits.filter(v=>v.clientId===id&&v.date>first.date&&v.date<=f.to).sort((a,b)=>(a.date+a.key).localeCompare(b.date+b.key));
    let x=months.get(month)||{month,clients:0,e30:0,r30:0,e60:0,r60:0,e90:0,r90:0};x.clients++;
    for(const w of [30,60,90]){let eligible=addDaysISO(first.date,w)<=f.to;if(eligible){x['e'+w]++;if(nexts.some(v=>v.date<=addDaysISO(first.date,w)))x['r'+w]++}}
    months.set(month,x)
  }
  return [...months.values()].sort((a,b)=>a.month.localeCompare(b.month))
}
function reportFirstExperience(data,f,newIds){
  let m=new Map();
  for(const id of (newIds||[])){
    let first=reportClientHistory(data,id,f.to)[0];if(!first)continue;let facts=reportVisitFacts(data,first).filter(s=>reportServiceMatches(s,f));if(!facts.length)facts=reportVisitFacts(data,first);
    let eligible30=addDaysISO(first.date,30)<=f.to,next30=data.visits.some(v=>v.clientId===id&&v.date>first.date&&v.date<=addDaysISO(first.date,30)&&v.date<=f.to);
    for(const s of facts){let key=s.serviceId||s.serviceName,label=s.serviceName||'Serviço';let x=m.get(key)||{key,label,base:0,e30:0,r30:0};x.base++;if(eligible30){x.e30++;if(next30)x.r30++}m.set(key,x)}
  }
  return [...m.values()].map(x=>({...x,rate30:reportPct(x.r30,x.e30)})).sort((a,b)=>b.base-a.base||b.rate30-a.rate30)
}
function reportAcquisitionQuality(data,f,m,field){
  let groups=new Map();
  for(const id of m.newIds){let c=reportClient(id),label=String(c?.[field]||'Não informado'),first=reportClientHistory(data,id,f.to)[0];if(!first)continue;let x=groups.get(label)||{label,clients:0,revenue:0,paidVisits:0,e30:0,r30:0};x.clients++;x.revenue+=Number(m.revenueBy.get(id)||0);let cv=m.visits.filter(v=>v.clientId===id),paid=cv.filter(v=>reportVisitRevenue(v,f,data)>0).length;x.paidVisits+=paid;let eligible=addDaysISO(first.date,30)<=f.to;if(eligible){x.e30++;let ret=data.visits.some(v=>v.clientId===id&&v.date>first.date&&v.date<=addDaysISO(first.date,30)&&v.date<=f.to);if(ret)x.r30++}groups.set(label,x)}
  return [...groups.values()].map(x=>({...x,ticket:x.paidVisits?x.revenue/x.paidVisits:0,return30:reportPct(x.r30,x.e30)})).sort((a,b)=>b.clients-a.clients||b.revenue-a.revenue)
}
function reportAttendanceRisk(m){
  let map=new Map();
  for(const b of m.missed){let x=map.get(b.clientId)||{clientId:b.clientId,missed:0,cancelled:0,total:0};x.missed++;x.total++;map.set(b.clientId,x)}
  for(const b of m.cancelled){let x=map.get(b.clientId)||{clientId:b.clientId,missed:0,cancelled:0,total:0};x.cancelled++;x.total++;map.set(b.clientId,x)}
  return [...map.values()].sort((a,b)=>b.missed-a.missed||b.total-a.total)
}
function reportCohortTransitions(data,f,currentVisits){
  let prevF=reportPreviousPeriod(f),prevVisits=reportPeriodVisits(data,prevF),prevIds=reportUniqueClients(prevVisits),curIds=new Set(reportUniqueClients(currentVisits)),retainedIds=prevIds.filter(id=>curIds.has(id));
  let records=[];
  for(const id of retainedIds){let prev=reportLastPeriodVisit(prevVisits,id),cur=reportFirstCurrentVisit(currentVisits,id);if(!prev||!cur)continue;let comparable=(prev.professionalIds||[]).length>0&&(cur.professionalIds||[]).length>0,samePro=comparable?reportIntersect(prev.professionalIds,cur.professionalIds):null,sameUnit=prev.unitId&&cur.unitId?prev.unitId===cur.unitId:null;records.push({clientId:id,prev,cur,comparable,samePro,sameUnit})}
  let comparable=records.filter(r=>r.comparable),sameProRecords=comparable.filter(r=>r.samePro===true),otherProRecords=comparable.filter(r=>r.samePro===false);
  let proMap=new Map();
  for(const id of prevIds){let prev=reportLastPeriodVisit(prevVisits,id);if(!prev)continue;let cur=curIds.has(id)?reportFirstCurrentVisit(currentVisits,id):null;for(const pid of reportUnique(prev.professionalIds||[])){let x=proMap.get(pid)||{id:pid,label:reportProName(pid),baseClients:new Set(),returnedClients:new Set(),sameClients:new Set(),otherClients:new Set(),records:[]};x.baseClients.add(id);if(cur){x.returnedClients.add(id);let same=(cur.professionalIds||[]).includes(pid);(same?x.sameClients:x.otherClients).add(id);x.records.push({clientId:id,prev,cur,same})}proMap.set(pid,x)}}
  let proRows=[...proMap.values()].map(x=>({id:x.id,label:x.label,base:x.baseClients.size,returned:x.returnedClients.size,same:x.sameClients.size,other:x.otherClients.size,retention:reportPct(x.returnedClients.size,x.baseClients.size),sameRate:reportPct(x.sameClients.size,x.returnedClients.size),otherRate:reportPct(x.otherClients.size,x.returnedClients.size),records:x.records})).sort((a,b)=>b.base-a.base);
  let unitMap=new Map(),migrationMap=new Map();
  for(const id of prevIds){let prev=reportLastPeriodVisit(prevVisits,id);if(!prev)continue;let cur=curIds.has(id)?reportFirstCurrentVisit(currentVisits,id):null,uid=prev.unitId||'none';let x=unitMap.get(uid)||{id:uid,label:reportUnitName(uid),base:new Set(),returned:new Set(),same:new Set(),other:new Set(),records:[]};x.base.add(id);if(cur){x.returned.add(id);let same=cur.unitId===prev.unitId;(same?x.same:x.other).add(id);x.records.push({clientId:id,prev,cur,same});if(!same){let mk=`${prev.unitId||'none'}>${cur.unitId||'none'}`,mx=migrationMap.get(mk)||{fromId:prev.unitId,toId:cur.unitId,from:reportUnitName(prev.unitId),to:reportUnitName(cur.unitId),clients:new Set()};mx.clients.add(id);migrationMap.set(mk,mx)}}unitMap.set(uid,x)}
  let unitRows=[...unitMap.values()].map(x=>({id:x.id,label:x.label,base:x.base.size,returned:x.returned.size,same:x.same.size,other:x.other.size,retention:reportPct(x.returned.size,x.base.size),records:x.records})).sort((a,b)=>b.base-a.base),migrations=[...migrationMap.values()].map(x=>({...x,count:x.clients.size})).sort((a,b)=>b.count-a.count);
  return {prevF,prevVisits,prevIds,retainedIds,records,comparable,sameProRecords,otherProRecords,proRows,unitRows,migrations}
}
function reportFunnel(m){
  let eligible=reportUnique(m.opps.map(o=>o.visit.clientId)).length,returned=reportUnique(m.opps.filter(o=>o.nextVisit).map(o=>o.visit.clientId)).length,onTime=reportUnique(m.opps.filter(o=>o.state==='ontime').map(o=>o.visit.clientId)).length,noReturn=reportUnique(m.opps.filter(o=>!o.nextVisit).map(o=>o.visit.clientId)).length,reactivation=reportUnique(m.reactivation.map(r=>r.clientId)).length;
  let same=reportUnique(m.opps.filter(o=>o.nextVisit&&reportIntersect(o.visit.professionalIds||[],o.nextVisit.professionalIds||[])).map(o=>o.visit.clientId)).length;
  return {attended:m.clientIds.length,eligible,returned,onTime,same,noReturn,reactivation}
}

const _reportMetricsV50=reportMetrics;
reportMetrics=function(data,f){
  let m=_reportMetricsV50(data,f);
  m.reactivation=reportEnrichReactivation(data,f,m.reactivation);
  m.reactivationPotential=m.reactivation.reduce((a,r)=>a+Number(r.potentialMonthly||0),0);
  m.portfolio=reportPortfolio(data,f);
  m.cohorts=reportCohorts(data,f,m.newIds);
  m.firstExperience=reportFirstExperience(data,f,m.newIds);
  m.originQuality=reportAcquisitionQuality(data,f,m,'origin');
  m.sourceQuality=reportAcquisitionQuality(data,f,m,'source');
  m.attendanceRisk=reportAttendanceRisk(m);
  m.transitions=reportCohortTransitions(data,f,m.visits);
  m.retainedIds=m.transitions.retainedIds;
  m.sameProIds=reportUnique(m.transitions.sameProRecords.map(r=>r.clientId));
  m.otherProIds=reportUnique(m.transitions.otherProRecords.map(r=>r.clientId));
  m.sameProRetention=reportPct(m.transitions.sameProRecords.length,m.transitions.comparable.length);
  m.otherProRetention=reportPct(m.transitions.otherProRecords.length,m.transitions.comparable.length);
  m.funnel=reportFunnel(m);
  return m
};

