function reportCohortTable(rows){return `<div class="report-table-wrap"><table class="report-table"><thead><tr><th>Coorte</th><th class="num">Novas</th><th class="num">Retorno 30d</th><th class="num">Retorno 60d</th><th class="num">Retorno 90d</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${escapeHtml(x.month.split('-').reverse().join('/'))}</td><td class="num">${x.clients}</td><td class="num">${x.e30?`${reportPctText(reportPct(x.r30,x.e30))} <small>(${x.r30}/${x.e30})</small>`:'—'}</td><td class="num">${x.e60?`${reportPctText(reportPct(x.r60,x.e60))} <small>(${x.r60}/${x.e60})</small>`:'—'}</td><td class="num">${x.e90?`${reportPctText(reportPct(x.r90,x.e90))} <small>(${x.r90}/${x.e90})</small>`:'—'}</td></tr>`).join(''):'<tr><td colspan="5"><div class="report-empty">Sem clientes novas elegíveis no período.</div></td></tr>'}</tbody></table></div>`}
