function reportFirstExperienceTable(rows){return `<div class="report-card"><h3>Retenção pela primeira experiência</h3><div class="sub">Serviços realizados na primeira visita da cliente. Uma primeira visita com vários serviços pode aparecer em mais de uma linha.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Serviço de entrada</th><th class="num">Clientes novas</th><th class="num">Elegíveis 30d</th><th class="num">Retornaram 30d</th><th class="num">Taxa</th></tr></thead><tbody>${rows.length?rows.slice(0,12).map(x=>`<tr><td>${escapeHtml(x.label)}</td><td class="num">${x.base}</td><td class="num">${x.e30}</td><td class="num">${x.r30}</td><td class="num">${x.e30?reportPctText(x.rate30):'—'}</td></tr>`).join(''):'<tr><td colspan="5"><div class="report-empty">Sem primeira experiência suficiente no período.</div></td></tr>'}</tbody></table></div></div>`}
function reportAttendanceRiskTable(rows){return `<div class="report-card"><h3>Clientes com faltas/cancelamentos recorrentes</h3><div class="sub">Ajuda a proteger capacidade da Agenda. Cancelamento e falta não contam como atendimento.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Cliente</th><th class="num">Faltas</th><th class="num">Cancelamentos</th><th class="num">Total</th><th></th></tr></thead><tbody>${rows.length?rows.slice(0,12).map(x=>`<tr><td>${escapeHtml(reportClient(x.clientId)?.name||'—')}</td><td class="num">${x.missed}</td><td class="num">${x.cancelled}</td><td class="num">${x.total}</td><td><button class="btn btn-ghost btn-sm" onclick="openReportDrilldown('client_attendance|${x.clientId}')">Ver</button></td></tr>`).join(''):'<tr><td colspan="5"><div class="report-empty">Sem faltas ou cancelamentos no período.</div></td></tr>'}</tbody></table></div></div>`}
function reportProfessionalReturnTable(rows){return `<div class="report-card"><h3>Retorno por profissional</h3><div class="sub">Coorte do período anterior equivalente. Compara a última profissional da coorte com a primeira volta da cliente no período atual.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Profissional anterior</th><th class="num">Base</th><th class="num">Voltaram</th><th class="num">Mesma profissional</th><th class="num">Outra profissional</th></tr></thead><tbody>${rows.length?rows.slice(0,20).map(x=>`<tr class="clickable" onclick="openReportDrilldown('pro_transition|${x.id}')"><td>${escapeHtml(x.label)}</td><td class="num">${x.base}</td><td class="num">${x.returned} <small>(${reportPctText(x.retention)})</small></td><td class="num">${x.same} <small>(${x.returned?reportPctText(x.sameRate):'—'})</small></td><td class="num">${x.other} <small>(${x.returned?reportPctText(x.otherRate):'—'})</small></td></tr>`).join(''):'<tr><td colspan="5"><div class="report-empty">Sem coorte profissional comparável.</div></td></tr>'}</tbody></table></div></div>`}
