function reportFunnelHtml(f){let steps=[['Atendidas',f.attended],['Elegíveis p/ retorno',f.eligible],['Retornaram',f.returned],['No prazo',f.onTime],['Mesma profissional',f.same],['Sem retorno',f.noReturn],['Reativação',f.reactivation]];return `<div class="report-card"><h3>Jornada gerencial de retorno</h3><div class="sub">Leitura operacional da carteira. As etapas não são um funil matemático estrito porque uma cliente pode gerar mais de uma oportunidade de retorno no período.</div><div class="report-funnel">${steps.map((x,i)=>`<div class="report-funnel-step"><span>${escapeHtml(x[0])}</span><b>${x[1]}</b></div>${i<steps.length-1?'<i>→</i>':''}`).join('')}</div></div>`}
