function v59ServiceFiltersHtml(){return `<div class="field"><label>Situação comercial</label><select id="repCommercial" onchange="reportsRefresh()"><option value="all">Todas</option><option value="normal" ${reportFilters.commercial==='normal'?'selected':''}>Sem redução comercial</option><option value="manual" ${reportFilters.commercial==='manual'?'selected':''}>Com desconto manual</option><option value="combo" ${reportFilters.commercial==='combo'?'selected':''}>Via combo</option><option value="partnership" ${reportFilters.commercial==='partnership'?'selected':''}>Modelo/Parceria</option><option value="other" ${reportFilters.commercial==='other'?'selected':''}>Outra redução</option></select></div><div class="field"><label>Combo</label><select id="repCombo" onchange="reportsRefresh()"><option value="all">Com ou sem combo</option><option value="with" ${reportFilters.combo==='with'?'selected':''}>Somente com combo</option><option value="without" ${reportFilters.combo==='without'?'selected':''}>Somente sem combo</option></select></div><div class="field"><label>Modelo/Parceria</label><select id="repPartnership" onchange="reportsRefresh()"><option value="all">Com ou sem parceria</option><option value="with" ${reportFilters.partnership==='with'?'selected':''}>Somente parceria</option><option value="without" ${reportFilters.partnership==='without'?'selected':''}>Somente normal</option></select></div>`}
