function v59ProServiceTable(m){return `<div class="report-card"><h3>Profissional × serviço</h3><div class="sub">A mesma profissional permanece separada por unidade.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Profissional</th><th>Unidade</th><th>Serviço</th><th class="num">Qtd.</th><th class="num">Faturamento</th><th class="num">Preço médio</th><th class="num">Comissão</th><th class="num">Insumos</th><th class="num">Margem parcial</th></tr></thead><tbody>${m.proServices.length?m.proServices.slice(0,40).map(r=>`<tr class="clickable" onclick="openReportDrilldown('service_pro|${encodeURIComponent(r.key)}')"><td><b>${escapeHtml(r.professional||'—')}</b></td><td>${escapeHtml(r.unit||'—')}</td><td>${escapeHtml(r.service||'—')}</td><td class="num">${reportNumber(r.qty,0)}</td><td class="num">${money(r.revenue)}</td><td class="num">${v59MaybeMoney(r.priceAvg)}</td><td class="num">${money(r.commission)}</td><td class="num">${v59MaybeMoney(r.input)}</td><td class="num">${v59MarginLabel(r)}</td></tr>`).join(''):'<tr><td colspan="9"><div class="report-empty">Sem produção para comparar.</div></td></tr>'}</tbody></table></div></div>`}
