function v59PartnershipTable(m){return `<div class="report-card"><h3>Modelo / Parceria</h3><div class="sub">A diferença comercial não é despesa; representa valor de tabela não cobrado.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Data</th><th>Comanda</th><th>Unidade</th><th class="num">Qtd.</th><th class="num">Tabela</th><th class="num">Cobrado</th><th class="num">Diferença</th><th class="num">Comissão</th></tr></thead><tbody>${m.partnerships.length?m.partnerships.map(r=>`<tr class="clickable" onclick="openReportDrilldown('service_partnership|${encodeURIComponent(r.commandId)}')"><td>${formatDateBR(r.date)}</td><td>${escapeHtml(r.commandId)}</td><td>${escapeHtml(reportUnitName(r.unitId))}</td><td class="num">${r.qty}</td><td class="num">${money(r.table)}</td><td class="num">${money(r.revenue)}</td><td class="num">${money(r.difference)}</td><td class="num">${money(r.commission)}</td></tr>`).join(''):'<tr><td colspan="8"><div class="report-empty">Nenhum atendimento de Modelo/Parceria no período.</div></td></tr>'}</tbody></table></div></div>`}
function renderReportServicesV59(s){let m=s.servicesCurrent,p=s.servicesPrevious,inputText=m.inputs===null?'—':money(m.inputs),inputSub=m.inputs===null?'Sem apropriação suficiente para este recorte.':m.inputPool?.partial?'Apenas custos diretamente rastreáveis neste filtro.':'Apropriação real disponível para o recorte.';return `<div class="report-section-head"><div><h2>Serviços</h2><div class="muted">Receita comercial histórica, descontos, comissão, insumos rastreáveis e margem de contribuição parcial.</div></div></div><div class="report-kpis">${reportKpi('Quantidade executada',reportNumber(m.qty,0),'Serviços em comandas finalizadas; componentes de combo contam individualmente.',reportDelta(m.qty,p.qty),'services_qty')}${reportKpi('Faturamento real',money(m.revenue),'Valor comercial efetivamente reconhecido.',reportDelta(m.revenue,p.revenue),'services_revenue')}${reportKpi('Preço médio praticado',m.priceAvg===null?'—':money(m.priceAvg),'Faturamento real ÷ quantidade executada.',m.priceAvg===null||p.priceAvg===null?'':reportDelta(m.priceAvg,p.priceAvg),'services_price')}${reportKpi('Valor de tabela',money(m.table),'Snapshot histórico antes das reduções comerciais.',reportDelta(m.table,p.table),'services_table')}${reportKpi('Desconto comercial',money(m.totalDiscount),`Manual ${money(m.manual)} · Combo ${money(m.combo)} · Parceria ${money(m.partnership)}.`,reportDelta(m.totalDiscount,p.totalDiscount),'services_discount')}${reportKpi('Comissão',money(m.commission),m.commissionUnknown?`${m.commissionUnknown} item(ns) sem comissão histórica comprovada.`:'CommissionEvents/snapshots congelados.',reportDelta(m.commission,p.commission),'services_commission')}${reportKpi('Insumos apropriados',inputText,inputSub,m.inputs===null||p.inputs===null?'':reportDelta(m.inputs,p.inputs),'services_inputs')}${reportKpi('Margem de contribuição parcial',money(m.margin),`${reportPctText(m.marginPct)} do faturamento · ${m.marginPartial?'há componentes sem atribuição completa.':'custos diretos disponíveis incluídos.'}`,reportDelta(m.margin,p.margin),'services_margin')}</div><div class="report-grid-2"><div class="report-card"><h3>Composição das reduções comerciais</h3><div class="report-status-list"><div><span>Desconto manual</span><b>${money(m.manual)}</b></div><div><span>Combo</span><b>${money(m.combo)}</b></div><div><span>Modelo/Parceria</span><b>${money(m.partnership)}</b></div><div><span>Outras reduções identificadas</span><b>${money(m.other)}</b></div></div></div><div class="report-card"><h3>Leitura de integridade</h3><div class="report-status-list"><div><span>Serviços via combo</span><b>${reportNumber(m.comboServiceQty,0)}</b></div><div><span>Participação do combo no faturamento</span><b>${m.revenue?reportPctText(m.comboRevenue/m.revenue*100):'—'}</b></div><div><span>Modelo/Parceria</span><b>${reportNumber(m.partnershipQty,0)}</b></div><div><span>Comissão legacy incerta</span><b>${m.uncertainCommissionCount}</b></div></div></div></div>${v59ServiceRankingTable(m)}${v59CategoryTable(m)}<div class="report-grid-2">${v59ComboTable(m)}${v59PartnershipTable(m)}</div>${v59ProServiceTable(m)}<div class="report-note"><b>Fórmula da margem:</b> receita comercial real − comissão historicamente registrada − insumos que possam ser atribuídos com segurança ao recorte. Quando o consumo existe apenas por categoria e o filtro exige serviço/profissional/cliente, o custo não é rateado artificialmente e a margem permanece explicitamente <b>parcial</b>. Não é lucro nem margem líquida.</div>`}
const _v59RenderReportsServicesBase=renderReports;
