function v59StockRm(v){return typeof roundMoney==='function'?roundMoney(Number(v||0)):Math.round((Number(v||0)+Number.EPSILON)*100)/100}
function v59StockFamilyMeta(p){let id=p?.familyId||'',f=(db.stockFamilies||[]).find(x=>x.id===id);return {id:id||`group:${p?.group||'sem-familia'}`,name:f?.name||p?.group||'Sem família'}}
function v59StockProductMeta(id,snapshot=null){let p=stockProduct(id)||null,sp=snapshot||null,f=sp?{id:sp.familyId||`group:${sp.group||'sem-familia'}`,name:sp.familyName||sp.group||'Sem família'}:v59StockFamilyMeta(p);return {p,f,name:sp?.name||p?.name||id||'Produto não identificado',sku:sp?.sku||p?.sku||'—',brand:sp?.brand||p?.brand||'—',unit:sp?.unit||p?.unit||'un',type:sp?.type||p?.type||'',packageQty:Number(sp?.packageQty??p?.packageQty??0),baseUnit:sp?.baseUnit||p?.baseUnit||'',legacyNoSnapshot:!sp}}
function v59StockLegacyMeta(productId){return {p:null,f:{id:`legacy:${productId||'unknown'}`,name:'Legado sem snapshot'},name:`Produto ${productId||'não identificado'} · legado sem snapshot`,sku:'—',brand:'—',unit:'un',type:'',packageQty:0,baseUnit:'',legacyNoSnapshot:true}}
function v59StockMovementMeta(m){return m?.productSnapshot?v59StockProductMeta(m.productId,m.productSnapshot):v59StockLegacyMeta(m?.productId)}
function v59StockPurchaseMeta(purchaseId,productId){let mv=(db.stockMovements||[]).find(m=>m.type==='PURCHASE'&&m.ref===purchaseId&&m.productId===productId&&m.productSnapshot);return mv?.productSnapshot?v59StockProductMeta(productId,mv.productSnapshot):v59StockLegacyMeta(productId)}
function v59StockLocationsForFilter(f){if(f.unit!=='all')return [f.unit];return ['central',...(db.units||[]).filter(u=>u.active!==false).map(u=>u.id)]}
function v59StockMovementInPeriod(m,f){return String(m.date||'')>=f.from&&String(m.date||'')<=f.to&&(f.unit==='all'||m.locationId===f.unit)}
function v59StockPurchaseLines(f){let out=[];for(const b of (db.stockPurchases||[])){if(String(b.date||'')<f.from||String(b.date||'')>f.to)continue;if(f.unit!=='all'&&b.destinationId!==f.unit)continue;let items=b.items||[],goods=Number(b.goods??items.reduce((s,i)=>s+Number(i.qty||0)*Number(i.unitCost||0),0)),freight=Number(b.freight||0);for(const i of items){let raw=Number(i.qty||0)*Number(i.unitCost||0),share=Number(i.freightShare??(goods?freight*(raw/goods):(items.length?freight/items.length:0))),landed=Number(i.landedUnitCost??(Number(i.unitCost||0)+(Number(i.qty||0)?share/Number(i.qty||0):0)));out.push({purchaseId:b.id,date:b.date,supplier:b.supplier||'—',unitId:b.destinationId,productId:i.productId,meta:v59StockPurchaseMeta(b.id,i.productId),qty:Number(i.qty||0),baseUnitCost:Number(i.unitCost||0),freightShare:v59StockRm(share),landedUnitCost:landed,total:v59StockRm(Number(i.qty||0)*landed),note:b.note||''})}}return out}
function v59StockTransferRows(f){return (db.stockTransfers||[]).filter(t=>String(t.date||'')>=f.from&&String(t.date||'')<=f.to&&(f.unit==='all'||t.sourceId===f.unit||t.destinationId===f.unit)).map(t=>({...t,value:v59StockRm((t.items||[]).reduce((s,i)=>s+Number(i.qty||0)*Number(i.unitCost||0),0)),qty:(t.items||[]).reduce((s,i)=>s+Number(i.qty||0),0)}))}
function v59StockConsumptionRows(f){return (db.stockMovements||[]).filter(m=>m.type==='CONSUMPTION'&&v59StockMovementInPeriod(m,f)).map(m=>({...m,meta:v59StockMovementMeta(m),qtyOut:Math.abs(Number(m.qty||0)),value:v59StockRm(Math.abs(Number(m.qty||0))*Number(m.unitCost||0))}))}
function v59StockCmvRows(f){return (db.stockMovements||[]).filter(m=>m.type==='SALE'&&v59StockMovementInPeriod(m,f)).map(m=>({...m,meta:v59StockMovementMeta(m),qtyOut:Math.abs(Number(m.qty||0)),value:v59StockRm(Math.abs(Number(m.qty||0))*Number(m.unitCost||0))}))}
