function v59StockCurrentRows(f){let locs=v59StockLocationsForFilter(f),rows=[];for(const b of (db.stockBalances||[])){if(!locs.includes(b.locationId))continue;let meta=v59StockProductMeta(b.productId),p=meta.p;if(!p)continue;let qty=Number(b.qty||0),cost=Number(b.avgCost||p.defaultCost||0),min=Number(p.minStock||0),status=qty<=0?'Sem estoque':min>0&&qty<=min*.5?'Crítico':min>0&&qty<=min?'Baixo':'Normal',last=v59StockLastOutbound(p.id,b.locationId,f.to,f.unit==='all'),days=last?Math.max(0,reportDaysBetween(last.date,f.to)):null;rows.push({productId:p.id,locationId:b.locationId,meta,qty,avgCost:cost,value:v59StockRm(qty*cost),min,status,lastOutbound:last?.date||'',daysWithoutOut:days})}return rows}
function v59StockBelowMin(f,current){let unitIds=f.unit==='all'?(db.units||[]).filter(u=>u.active!==false).map(u=>u.id):[f.unit],rows=[];for(const uid of unitIds){for(const p of (db.stockProducts||[]).filter(p=>p.active!==false&&Number(p.minStock||0)>0)){let b=(db.stockBalances||[]).find(x=>x.productId===p.id&&x.locationId===uid),qty=Number(b?.qty||0),min=Number(p.minStock||0);if(qty<=min)rows.push({productId:p.id,unitId:uid,qty,min,difference:qty-min,meta:v59StockProductMeta(p.id)})}}return rows}
function v59StockFamilyRows(current,purchases,consumption,losses){let map=new Map(),ensure=(pid,meta0=null)=>{let meta=meta0||v59StockProductMeta(pid),k=meta.f.id,r=map.get(k)||{id:k,name:meta.f.name,currentValue:0,currentQty:0,purchases:0,consumption:0,losses:0,skus:new Set()};r.skus.add(meta.sku||pid);map.set(k,r);return r};for(const x of current){let r=ensure(x.productId,x.meta);r.currentValue+=x.value;r.currentQty+=x.qty}for(const x of purchases)ensure(x.productId,x.meta).purchases+=x.total;for(const x of consumption)ensure(x.productId,x.meta).consumption+=x.value;for(const x of losses)ensure(x.productId,x.meta).losses+=x.value;return [...map.values()].map(r=>({...r,currentValue:v59StockRm(r.currentValue),purchases:v59StockRm(r.purchases),consumption:v59StockRm(r.consumption),losses:v59StockRm(r.losses),skuCount:r.skus.size})).sort((a,b)=>b.currentValue-a.currentValue)}
function v59StockSkuRows(current,purchases,consumption,losses){let map=new Map(),ensure=(pid,meta0=null)=>{let meta=meta0||v59StockProductMeta(pid),key=`${pid}|${meta.sku}|${meta.f.id}`,r=map.get(key)||{productId:pid,meta,currentQty:0,currentValue:0,currentCost:null,purchases:0,purchasedQty:0,consumption:0,consumedQty:0,losses:0,lossQty:0};map.set(key,r);return r};for(const x of current){let r=ensure(x.productId,x.meta);r.currentQty+=x.qty;r.currentValue+=x.value}for(const x of purchases){let r=ensure(x.productId,x.meta);r.purchases+=x.total;r.purchasedQty+=x.qty}for(const x of consumption){let r=ensure(x.productId,x.meta);r.consumption+=x.value;r.consumedQty+=x.qtyOut}for(const x of losses){let r=ensure(x.productId,x.meta);r.losses+=x.value;r.lossQty+=x.qtyOut}for(const r of map.values())r.currentCost=r.currentQty?v59StockRm(r.currentValue/r.currentQty):null;return [...map.values()].map(r=>({...r,currentValue:v59StockRm(r.currentValue),purchases:v59StockRm(r.purchases),consumption:v59StockRm(r.consumption),losses:v59StockRm(r.losses)})).sort((a,b)=>b.currentValue-a.currentValue)}
function v59StockBrandRows(current,consumption){let cur=new Map();for(const x of current){let r=cur.get(x.productId)||{productId:x.productId,meta:x.meta,qty:0,value:0};r.qty+=x.qty;r.value+=x.value;cur.set(x.productId,r)}let fam=new Map();for(const r of cur.values()){let m=r.meta,p=m.p;if(!p?.familyId||!(Number(p.packageQty)>0)||!p.baseUnit)continue;let k=p.familyId,arr=fam.get(k)||[],consumed=consumption.filter(c=>c.productId===p.id),consQty=consumed.reduce((s,c)=>s+c.qtyOut*Number(c.meta?.packageQty||p.packageQty||0),0),consCost=consumed.reduce((s,c)=>s+c.value,0),avgCost=r.qty?r.value/r.qty:Number(p.defaultCost||0);arr.push({productId:p.id,family:m.f.name,product:m.name,brand:m.brand,baseUnit:p.baseUnit,packageQty:Number(p.packageQty),technicalUnitCost:avgCost/Number(p.packageQty),consumedTechnicalQty:consQty,observedConsumptionCost:consCost,observedConsumptionUnitCost:consQty?consCost/consQty:null});fam.set(k,arr)}let out=[];for(const arr of fam.values()){let units=new Set(arr.map(x=>x.baseUnit));if(arr.length>=2&&units.size===1)out.push(...arr)}return out.sort((a,b)=>a.family.localeCompare(b.family)||a.technicalUnitCost-b.technicalUnitCost)}
function v59StockSubstitutionRows(f){let out=[];for(const s of (db.stockSubstitutions||[]).filter(x=>String(x.date||'')<=f.to)){let old=s.fromSnapshot?v59StockProductMeta(s.fromProductId,s.fromSnapshot):v59StockLegacyMeta(s.fromProductId),neu=s.toSnapshot?v59StockProductMeta(s.toProductId,s.toSnapshot):v59StockLegacyMeta(s.toProductId);if(!s.fromSnapshot||!s.toSnapshot||!old.packageQty||!neu.packageQty||!old.baseUnit||old.baseUnit!==neu.baseUnit){out.push({...s,old,neu,before:null,after:null,change:null,sufficient:false,legacyNoSnapshot:!s.fromSnapshot||!s.toSnapshot});continue}let preFrom=addDaysISO(s.date,-30),preTo=addDaysISO(s.date,-1),postFrom=s.date,postTo=addDaysISO(s.date,29),calc=(pid,meta,from,to)=>{let ms=(db.stockMovements||[]).filter(m=>m.type==='CONSUMPTION'&&m.productId===pid&&String(m.date||'')>=from&&String(m.date||'')<=to&&(f.unit==='all'||m.locationId===f.unit));let tq=ms.reduce((q,m)=>{let mm=v59StockMovementMeta(m),pack=Number(mm.packageQty||meta.packageQty||0);return q+Math.abs(Number(m.qty||0))*pack},0),cost=ms.reduce((q,m)=>q+Math.abs(Number(m.qty||0))*Number(m.unitCost||0),0);return {samples:ms.length,technicalQty:tq,cost:v59StockRm(cost),unitCost:tq?cost/tq:null}};let before=calc(s.fromProductId,old,preFrom,preTo),after=calc(s.toProductId,neu,postFrom,postTo),sufficient=!!(before.unitCost&&after.unitCost),change=sufficient?(after.unitCost-before.unitCost)/before.unitCost*100:null;out.push({...s,old,neu,before,after,change,sufficient,legacyNoSnapshot:false})}return out.sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
function v59StockMetrics(f){let current=v59StockCurrentRows(f),purchases=v59StockPurchaseLines(f),transfers=v59StockTransferRows(f),consumption=v59StockConsumptionRows(f),cmv=v59StockCmvRows(f),losses=v59StockLossRows(f),appropriations=v59StockAppropriationRows(f),below=v59StockBelowMin(f,current),families=v59StockFamilyRows(current,purchases,consumption,losses),skus=v59StockSkuRows(current,purchases,consumption,losses),brands=v59StockBrandRows(current,consumption),substitutions=v59StockSubstitutionRows(f),currentValue=v59StockRm(current.reduce((s,x)=>s+x.value,0)),currentQty=current.reduce((s,x)=>s+x.qty,0),purchaseValue=v59StockRm(purchases.reduce((s,x)=>s+x.total,0)),consumptionValue=v59StockRm(consumption.reduce((s,x)=>s+x.value,0)),cmvValue=v59StockRm(cmv.reduce((s,x)=>s+x.value,0)),lossValue=v59StockRm(losses.reduce((s,x)=>s+x.value,0)),transferValue=v59StockRm(transfers.reduce((s,x)=>s+x.value,0)),appropriatedValue=v59StockRm(appropriations.reduce((s,x)=>s+x.value,0)),outQty=consumption.reduce((s,x)=>s+x.qtyOut,0)+cmv.reduce((s,x)=>s+x.qtyOut,0)+losses.reduce((s,x)=>s+x.qtyOut,0),velocity=currentQty>0?outQty/currentQty:null,stopped=current.filter(x=>x.qty>0).map(x=>({...x,band:x.daysWithoutOut===null?'Sem saída registrada':x.daysWithoutOut<=30?'Até 30 dias':x.daysWithoutOut<=60?'31–60 dias':x.daysWithoutOut<=90?'61–90 dias':'Acima de 90 dias'})).sort((a,b)=>(b.daysWithoutOut??99999)-(a.daysWithoutOut??99999));return {f,current,purchases,transfers,consumption,cmv,losses,appropriations,below,families,skus,brands,substitutions,stopped,currentValue,currentQty,activeSkuWithStock:new Set(current.filter(x=>x.qty>0&&x.meta.p?.active!==false).map(x=>x.productId)).size,purchaseValue,consumptionValue,cmvValue,lossValue,transferValue,transferEconomicImpact:0,appropriatedValue,velocity}}
function v59StockStatusBadge(s){let cls=s==='Normal'?'good':s==='Baixo'?'warn':s==='Crítico'||s==='Sem estoque'?'bad':'';return `<span class="report-badge ${cls}">${escapeHtml(s)}</span>`}
function v59StockCurrentTable(m){let rows=m.current.slice().sort((a,b)=>b.value-a.value);return `<div class="report-card"><h3>Estoque atual</h3><div class="sub">Posição atual: saldo físico × custo médio. O filtro de período afeta os fluxos; a posição representa o estoque existente agora.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>SKU / Produto</th><th>Família</th><th>Marca</th><th>Local</th><th class="num">Qtd.</th><th class="num">Custo médio</th><th class="num">Valor</th><th class="num">Mín.</th><th>Situação</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td><b>${escapeHtml(x.meta.sku)}</b><div class="muted">${escapeHtml(x.meta.name)}</div></td><td>${escapeHtml(x.meta.f.name)}</td><td>${escapeHtml(x.meta.brand)}</td><td>${escapeHtml(stockLocationName(x.locationId))}</td><td class="num">${reportNumber(x.qty,2)} ${escapeHtml(x.meta.unit)}</td><td class="num">${money(x.avgCost)}</td><td class="num"><b>${money(x.value)}</b></td><td class="num">${reportNumber(x.min,2)}</td><td>${v59StockStatusBadge(x.status)}</td></tr>`).join(''):'<tr><td colspan="9"><div class="report-empty">Sem saldos de estoque neste recorte.</div></td></tr>'}</tbody></table></div></div>`}
function v59StockFlowTables(m){return `<div class="report-grid-2"><div class="report-card"><h3>Famílias</h3><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Família</th><th class="num">SKUs</th><th class="num">Estoque</th><th class="num">Compras</th><th class="num">Consumo</th><th class="num">Perdas</th></tr></thead><tbody>${m.families.length?m.families.map(x=>`<tr><td><b>${escapeHtml(x.name)}</b></td><td class="num">${x.skuCount}</td><td class="num">${money(x.currentValue)}</td><td class="num">${money(x.purchases)}</td><td class="num">${money(x.consumption)}</td><td class="num">${money(x.losses)}</td></tr>`).join(''):'<tr><td colspan="6"><div class="report-empty">Sem dados por família.</div></td></tr>'}</tbody></table></div></div><div class="report-card"><h3>SKUs</h3><div class="report-table-wrap"><table class="report-table"><thead><tr><th>SKU / Produto</th><th class="num">Qtd. atual</th><th class="num">Valor atual</th><th class="num">Compras</th><th class="num">Consumo</th><th class="num">Perdas</th></tr></thead><tbody>${m.skus.length?m.skus.slice(0,20).map(x=>`<tr><td><b>${escapeHtml(x.meta.sku)}</b><div class="muted">${escapeHtml(x.meta.name)}</div></td><td class="num">${reportNumber(x.currentQty,2)}</td><td class="num">${money(x.currentValue)}</td><td class="num">${money(x.purchases)}</td><td class="num">${money(x.consumption)}</td><td class="num">${money(x.losses)}</td></tr>`).join(''):'<tr><td colspan="6"><div class="report-empty">Sem movimentação por SKU.</div></td></tr>'}</tbody></table></div></div></div>`}
function v59StockStoppedTable(m){return `<div class="report-card"><h3>Tempo sem saída</h3><div class="sub">Fato observado pela última saída real. No consolidado, transferência interna não reinicia o relógio. Não significa automaticamente desperdício.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Produto</th><th>Local</th><th>Última saída</th><th class="num">Dias</th><th>Faixa</th><th class="num">Valor atual</th></tr></thead><tbody>${m.stopped.length?m.stopped.slice(0,30).map(x=>`<tr><td><b>${escapeHtml(x.meta.name)}</b></td><td>${escapeHtml(stockLocationName(x.locationId))}</td><td>${x.lastOutbound?formatDateBR(x.lastOutbound):'Sem saída registrada'}</td><td class="num">${x.daysWithoutOut===null?'—':x.daysWithoutOut}</td><td>${escapeHtml(x.band)}</td><td class="num">${money(x.value)}</td></tr>`).join(''):'<tr><td colspan="6"><div class="report-empty">Sem itens com saldo.</div></td></tr>'}</tbody></table></div></div>`}
function v59StockBrandTable(m){return `<div class="report-card"><h3>Comparação de marcas dentro da mesma família</h3><div class="sub">Somente SKUs com embalagem e unidade técnica compatíveis. Custo técnico atual = custo médio ÷ conteúdo da embalagem.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Família</th><th>Marca / Produto</th><th class="num">Conteúdo</th><th class="num">Custo / unidade técnica</th><th class="num">Consumo observado</th><th class="num">Custo observado / unidade técnica</th></tr></thead><tbody>${m.brands.length?m.brands.map(x=>`<tr><td>${escapeHtml(x.family)}</td><td><b>${escapeHtml(x.brand)}</b><div class="muted">${escapeHtml(x.product)}</div></td><td class="num">${reportNumber(x.packageQty,2)} ${escapeHtml(x.baseUnit)}</td><td class="num">${money(x.technicalUnitCost)}</td><td class="num">${reportNumber(x.consumedTechnicalQty,2)} ${escapeHtml(x.baseUnit)}</td><td class="num">${x.observedConsumptionUnitCost===null?'—':money(x.observedConsumptionUnitCost)}</td></tr>`).join(''):'<tr><td colspan="6"><div class="report-empty">Sem SKUs comparáveis com unidade técnica suficiente.</div></td></tr>'}</tbody></table></div></div>`}
function v59StockSubstitutionTable(m){return `<div class="report-card"><h3>Substituições observadas</h3><div class="sub">Compara custo técnico observado nos 30 dias anteriores e posteriores quando existe amostra. Não atribui causalidade.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Data</th><th>Anterior</th><th>Novo</th><th>Motivo</th><th class="num">Custo antes</th><th class="num">Custo depois</th><th class="num">Variação observada</th></tr></thead><tbody>${m.substitutions.length?m.substitutions.map(x=>`<tr><td>${formatDateBR(x.date)}</td><td>${escapeHtml(x.old.name)}</td><td>${escapeHtml(x.neu.name)}</td><td>${escapeHtml(x.reason||'—')}</td><td class="num">${x.before?.unitCost?money(x.before.unitCost):'—'}</td><td class="num">${x.after?.unitCost?money(x.after.unitCost):'—'}</td><td class="num">${x.sufficient?`${x.change>0?'+':''}${reportNumber(x.change,1)}%`:'Sem dados suficientes'}</td></tr>`).join(''):'<tr><td colspan="7"><div class="report-empty">Nenhuma substituição registrada.</div></td></tr>'}</tbody></table></div></div>`}
function v59StockBelowTable(m){return `<div class="report-card"><h3>Abaixo do estoque mínimo</h3><div class="report-table-wrap"><table class="report-table"><thead><tr><th>SKU / Produto</th><th>Unidade</th><th class="num">Atual</th><th class="num">Mínimo</th><th class="num">Diferença</th></tr></thead><tbody>${m.below.length?m.below.map(x=>`<tr><td><b>${escapeHtml(x.meta.sku)}</b><div class="muted">${escapeHtml(x.meta.name)}</div></td><td>${escapeHtml(reportUnitName(x.unitId))}</td><td class="num">${reportNumber(x.qty,2)}</td><td class="num">${reportNumber(x.min,2)}</td><td class="num">${reportNumber(x.difference,2)}</td></tr>`).join(''):'<tr><td colspan="5"><div class="report-empty">Nenhum SKU abaixo do mínimo.</div></td></tr>'}</tbody></table></div></div>`}
function renderReportStockV59(s){let m=s.stockCurrent,p=s.stockPrevious,vel=m.velocity===null?'—':reportNumber(m.velocity,2)+'×';return `<div class="report-section-head"><div><h2>Estoque</h2><div class="muted">Posição atual + movimentações reais do período. Transferências internas são operacionais e têm impacto econômico consolidado zero.</div></div></div><div class="report-kpis">${reportKpi('Valor atual do estoque',money(m.currentValue),'Saldo físico atual × custo médio; posição atual, não fotografia histórica.', '', 'stock_value')}${reportKpi('SKUs ativos com saldo',reportNumber(m.activeSkuWithStock,0),'Produtos ativos com saldo positivo no recorte atual.','','stock_current')}${reportKpi('Compras no período',money(m.purchaseValue),'Mercadorias + frete capitalizado.',reportDelta(m.purchaseValue,p.purchaseValue),'stock_purchases')}${reportKpi('Consumo de insumos',money(m.consumptionValue),'Saída operacional; não é CMV de revenda.',reportDelta(m.consumptionValue,p.consumptionValue),'stock_consumption')}${reportKpi('CMV de revenda',money(m.cmvValue),'Somente produtos de revenda efetivamente vendidos.',reportDelta(m.cmvValue,p.cmvValue),'stock_cmv')}${reportKpi('Perdas / ajustes negativos',money(m.lossValue),'Inventário negativo/perda ao custo registrado.',reportDelta(m.lossValue,p.lossValue),'stock_losses')}${reportKpi('Transferências',money(m.transferValue),'Volume operacional transferido · impacto econômico consolidado R$ 0,00.',reportDelta(m.transferValue,p.transferValue),'stock_transfers')}${reportKpi('Abaixo do mínimo',reportNumber(m.below.length,0),'Ocorrências SKU × unidade abaixo ou iguais ao mínimo.','','stock_below')}${reportKpi('Velocidade de saída',vel,'Saídas econômicas do período ÷ estoque atual. Não é giro contábil, pois não há estoque médio histórico confiável.',m.velocity===null||p.velocity===null?'':reportDelta(m.velocity,p.velocity),'stock_velocity')}</div><div class="report-grid-2"><div class="report-card"><h3>Consumo × apropriação</h3><div class="report-status-list"><div><span>Consumo físico de insumos</span><b>${money(m.consumptionValue)}</b></div><div><span>Apropriado a categorias/serviços</span><b>${money(m.appropriatedValue)}</b></div><div><span>Diferença não apropriada/rastreável</span><b>${money(Math.max(0,v59StockRm(m.consumptionValue-m.appropriatedValue)))}</b></div></div></div><div class="report-card"><h3>Regra econômica</h3><div class="report-status-list"><div><span>Transferência interna</span><b>R$ 0,00 de custo</b></div><div><span>Compra capitalizada</span><b>Estoque</b></div><div><span>Produto revendido</span><b>CMV</b></div><div><span>Insumo consumido</span><b>Custo de serviço</b></div></div></div></div>${v59StockCurrentTable(m)}${v59StockFlowTables(m)}${v59StockBelowTable(m)}${v59StockStoppedTable(m)}${v59StockBrandTable(m)}${v59StockSubstitutionTable(m)}<div class="report-note"><b>Importante:</b> “Velocidade de saída” não é chamada de giro porque o protótipo não possui snapshots de estoque médio por período suficientemente confiáveis. Transferência entre locais nunca é classificada como consumo, CMV ou despesa.</div>`}
