 function v60ReceivablePaidUntil(receivableId,to){let paid=0;for(const p of (db.clientReceivablePayments||[])){if(String(p.date||'')>String(to))continue;let alloc=Array.isArray(p.allocations)?p.allocations:[];let hits=alloc.filter(a=>a.receivableId===receivableId);if(hits.length){paid+=hits.reduce((s,a)=>s+Number(a.amount||0),0);continue}let ids=Array.isArray(p.receivableIds)?p.receivableIds:[];if(ids.length===1&&ids[0]===receivableId)paid+=Number(p.amount||0)}return rm(paid)}
