 function v60ReceivableGenerated(f){let rows=(db.clientReceivables||[]).filter(r=>inRange(r.date,f)&&unitOk(f,r.unitId));return {rows,total:rm(rows.reduce((s,r)=>s+Number(r.originalAmount??r.amount??0),0))}}
 function v60Payables(f){let rows=[];for(const e of (db.demoFinancialEntries||[])){if(Number(e.amount||0)>=0||e.excludedFromOperationalLedger===true)continue;let created=e.originalDate||e.dueDate||e.date||'',paidDate=e.status==='Previsto'?'':(e.paidDate||e.date||'');if(!created||String(created)>String(f.to)||!unitOk(f,e.unitId))continue;let openAtCutoff=e.status==='Previsto'||!paidDate||String(paidDate)>String(f.to);if(!openAtCutoff)continue;rows.push({...e,reportAmount:rm(Math.abs(Number(e.amount||0))),reportDueDate:e.dueDate||'',overdue:!!e.dueDate&&String(e.dueDate)<String(f.to)})}return rows.sort((a,b)=>String(a.reportDueDate||'9999').localeCompare(String(b.reportDueDate||'9999')))}
 function v60PaidPayables(f){let rows=(db.demoFinancialEntries||[]).filter(e=>Number(e.amount||0)<0&&e.status!=='Previsto'&&inRange(e.date,f)&&unitOk(f,e.unitId)&&e.sourceType==='stock_purchase');return {rows,total:rm(rows.reduce((s,e)=>s+Math.abs(Number(e.amount||0)),0))}}
 function v60AccountRows(f){let ledger=v60LedgerUntil(f),period=v60LedgerRows(f);return (db.financialAccounts||[]).filter(a=>a.active!==false&&unitOk(f,a.unitId)).map(a=>{let bal=rm(ledger.filter(e=>accountMatches(a,e)).reduce((s,e)=>s+Number(e.amount||0),0)),mov=rm(period.filter(e=>accountMatches(a,e)).reduce((s,e)=>s+Number(e.amount||0),0));return {...a,balanceAtCutoff:bal,periodMovement:mov}})}
 function v60PaymentMethods(f){let map=new Map();for(const m of v60FrozenReceiptMovements(f)){let k=m.paymentMethod||'Não identificado',x=map.get(k)||{name:k,count:0,gross:0,fees:0,net:0};x.count++;x.gross+=Number(m.amount||0);x.fees+=Number(m.processorFee||0);map.set(k,x)}return [...map.values()].map(x=>({...x,gross:rm(x.gross),fees:rm(x.fees),net:rm(x.gross-x.fees)})).sort((a,b)=>b.gross-a.gross)}
 function v60ReceivableSchedule(rows,cutoff){let g={overdue:0,d7:0,d30:0,later:0,undated:0};for(const r of rows){let v=Number(r.balanceAtCutoff||0);if(!r.dueDate){g.undated+=v;continue}let days=reportDaysBetween?reportDaysBetween(cutoff,r.dueDate):0;if(String(r.dueDate)<String(cutoff))g.overdue+=v;else if(days<=7)g.d7+=v;else if(days<=30)g.d30+=v;else g.later+=v}Object.keys(g).forEach(k=>g[k]=rm(g[k]));return g}
