 function v60FinanceMetrics(f){let ledger=v60LedgerRows(f),incoming=rm(ledger.filter(e=>Number(e.amount||0)>=0).reduce((s,e)=>s+Number(e.amount||0),0)),outgoing=rm(ledger.filter(e=>Number(e.amount||0)<0).reduce((s,e)=>s+Math.abs(Number(e.amount||0)),0)),receipts=v60FrozenReceiptMovements(f),fees=rm(receipts.reduce((s,m)=>s+Number(m.processorFee||0),0)),receivables=v60Receivables(f),receivableBalance=rm(receivables.reduce((s,r)=>s+Number(r.balanceAtCutoff||0),0)),overdueReceivables=receivables.filter(r=>r.overdue),payables=v60Payables(f),payableBalance=rm(payables.reduce((s,r)=>s+Number(r.reportAmount||0),0)),overduePayables=payables.filter(r=>r.overdue),collected=v60ReceivableCollected(f),generated=v60ReceivableGenerated(f),paidPayables=v60PaidPayables(f),methods=v60PaymentMethods(f),accounts=v60AccountRows(f),closures=ledger.filter(e=>e.sourceType==='cash_closure'),receivableSchedule=v60ReceivableSchedule(receivables,f.to),payableSchedule=v60PayableSchedule(payables,f.to);return {f,ledger,incoming,outgoing,net:rm(incoming-outgoing),receipts,fees,receivables,receivableBalance,overdueReceivables,payables,payableBalance,overduePayables,collected,generated,paidPayables,methods,accounts,closures,receivableSchedule,payableSchedule}}
