 function v61FrozenReceipts(f,until=false){let out=[],seen=new Set();for(const row of financeClosedCashRows()){if(until?String(row.date||'')>String(f.to):!v61InRange(row.date,f))continue;if(!v61UnitOk(f,row.unitId))continue;for(const m of (row.movements||[])){if(seen.has(m.id))continue;seen.add(m.id);out.push(m)}}return out}
 function v61ReceivablePaidUntil(id,to){let paid=0;for(const p of (db.clientReceivablePayments||[])){if(String(p.date||'')>String(to))continue;let hits=(p.allocations||[]).filter(a=>a.receivableId===id);paid+=hits.reduce((s,a)=>s+Number(a.amount||0),0)}return rm(paid)}
 function v61ClientReceivables(f){let rows=[];for(const r of (db.clientReceivables||[])){if(!v61UnitOk(f,r.unitId)||String(r.date||'')>String(f.to))continue;let original=Number(r.originalAmount??r.amount??0),paid=v61ReceivablePaidUntil(r.id,f.to),balance=rm(Math.max(0,original-paid));if(balance<=.009)continue;rows.push({...r,sourceUnitId:r.unitId,originalAmount:rm(original),paidAtCutoff:paid,balanceAtCutoff:balance,overdue:!!r.dueDate&&String(r.dueDate)<String(f.to)})}return rows}
 function v61ProcessorReceivables(f){let rows=[];for(const m of v61FrozenReceipts(f,true)){let a=(db.financialAccounts||[]).find(x=>x.id===(m.financialAccountId||m.accountId));if(!a||a.type!=='PROCESSOR')continue;if(!v61UnitOk(f,a.unitId))continue;let gross=rm(Number(m.grossAmount??m.amount??0)),fee=rm(Number(m.processorFee||0));rows.push({id:m.id,date:m.date,unitId:a.unitId,accountId:a.id,account:a.name,paymentMethod:m.paymentMethod||'—',gross,fee,net:rm(gross-fee),expectedSettlementDate:m.expectedSettlementDate||'',settlementReliability:m.settlementReliability||'unknown',status:m.settlementReliability==='snapshot'?'A liquidar / sem conciliação externa':'Prazo histórico não disponível'})}return rows}
 function v61ReceivableGenerated(f){let rs=(db.clientReceivables||[]).filter(r=>v61UnitOk(f,r.unitId)&&v61InRange(r.date,f));return {rows:rs,total:rm(rs.reduce((s,r)=>s+Number(r.originalAmount??r.amount??0),0))}}
 function v61ReceivableCollected(f){let rows=(db.clientReceivablePayments||[]).filter(p=>v61InRange(p.date,f)&&((p.allocations||[]).some(a=>v61UnitOk(f,a.unitId))||f.unit==='all'));let total=0;for(const p of rows){if(f.unit==='all')total+=Number(p.amount||0);else total+=(p.allocations||[]).filter(a=>a.unitId===f.unit).reduce((s,a)=>s+Number(a.amount||0),0)}return {rows,total:rm(total)}}
 function v61AccountRows(f){return (db.financialAccounts||[]).filter(a=>{if(!v61UnitOk(f,a.unitId))return false;if(a.active!==false)return true;let hasLedger=v61LedgerFlowsForAccount(a,f.from,f.to).length>0,hasSupply=v61SupplyMovements(a,f.from,f.to).length>0,hasProcessor=a.type==='PROCESSOR'&&v61ProcessorFacts(a,f.from,f.to).rows.length>0;return hasLedger||hasSupply||hasProcessor}).map(a=>({...a,...v61AccountSnapshot(a,f.to,f.from),inactiveCurrently:a.active===false}))}
 function v61PaymentMethods(f){let map=new Map();for(const m of v61FrozenReceipts(f)){let k=m.paymentMethod||'Não identificado',x=map.get(k)||{name:k,count:0,gross:0,fees:0,net:0};x.count++;x.gross+=Number(m.grossAmount??m.amount??0);x.fees+=Number(m.processorFee||0);map.set(k,x)}return [...map.values()].map(x=>({...x,gross:rm(x.gross),fees:rm(x.fees),net:rm(x.gross-x.fees)})).sort((a,b)=>b.gross-a.gross)}
 function v61UnitDreRows(f){let ids=new Set();for(const u of (db.units||[]))if(u.active!==false)ids.add(u.id);let hist=v61HistoricalIds(f);for(const id of hist.units)ids.add(id);if(f.unit!=='all')ids=new Set([f.unit]);return [...ids].map(id=>{let u=(db.units||[]).find(x=>x.id===id)||{id,name:id,active:false};return {unit:u,data:financeDreDataV40({from:f.from,to:f.to,unit:id})}})}
 function v61FinanceMetrics(f){let ledger=v61LedgerRows(f),incoming=rm(ledger.filter(e=>Number(e.amount||0)>=0).reduce((s,e)=>s+Number(e.amount||0),0)),outgoing=rm(ledger.filter(e=>Number(e.amount||0)<0).reduce((s,e)=>s+Math.abs(Number(e.amount||0)),0)),receipts=v61FrozenReceipts(f),fees=rm(receipts.reduce((s,m)=>s+Number(m.processorFee||0),0)),clients=v61ClientReceivables(f),processor=v61ProcessorReceivables(f),payables=v61Payables(f),accounts=v61AccountRows(f),professionals=v61ProfessionalObligations(f),generated=v61ReceivableGenerated(f),collected=v61ReceivableCollected(f),methods=v61PaymentMethods(f),closures=ledger.filter(e=>e.sourceType==='cash_closure');let clientBalance=rm(clients.reduce((s,r)=>s+Number(r.balanceAtCutoff||0),0)),processorBalance=rm(processor.reduce((s,r)=>s+Number(r.net||0),0)),payableBalance=rm(payables.reduce((s,r)=>s+Number(r.reportAmount||0),0)),professionalBalance=rm(professionals.reduce((s,r)=>s+Math.max(0,Number(r.balance||0)),0));return {f,ledger,incoming,outgoing,fees,netBeforeFees:rm(incoming-outgoing),netAfterFees:rm(incoming-outgoing-fees),net:rm(incoming-outgoing-fees),receipts,clientReceivables:clients,receivables:clients,clientReceivableBalance:clientBalance,receivableBalance:clientBalance,processorReceivables:processor,processorReceivableBalance:processorBalance,overdueReceivables:clients.filter(r=>r.overdue),payables,payableBalance,overduePayables:payables.filter(r=>r.overdue),professionalObligations:professionals,professionalBalance,generated,collected,methods,accounts,closures}}
 function v61FinanceState(f){return {finance:v61FinanceMetrics(f),dre:financeDreDataV40({from:f.from,to:f.to,unit:f.unit}),units:v61UnitDreRows(f)}}

 function v61ProcessorTable(rows){return `<div class="report-card"><h3>Recebíveis de adquirentes</h3><div class="sub">Somente prazo congelado no fato novo. Sem confirmação bancária, o líquido conhecido continua classificado como a liquidar.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Data</th><th>Conta</th><th>Forma</th><th class="num">Bruto</th><th class="num">Taxa</th><th class="num">Líquido conhecido</th><th>Liquidação prevista</th></tr></thead><tbody>${rows.length?rows.slice(0,40).map(r=>`<tr><td>${formatDateBR(r.date)}</td><td>${escapeHtml(r.account)}${(db.financialAccounts||[]).find(a=>a.id===r.accountId)?.active===false?' <span class="v61-status off">inativa</span>':''}</td><td>${escapeHtml(r.paymentMethod)}</td><td class="num">${money(r.gross)}</td><td class="num">${money(r.fee)}</td><td class="num"><b>${money(r.net)}</b></td><td>${r.settlementReliability==='snapshot'?formatDateBR(r.expectedSettlementDate):'<span class="v61-status warn">prazo histórico não disponível</span>'}</td></tr>`).join(''):'<tr><td colspan="7"><div class="report-empty">Sem recebíveis de adquirentes identificáveis.</div></td></tr>'}</tbody></table></div></div>`}
 function v61ProfessionalsTable(rows){return `<div class="report-card"><h3>Obrigações com profissionais</h3><div class="sub">Posição de obrigação. O custo de comissão/remuneração continua reconhecido uma única vez na DRE.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Profissional</th><th>Unidade</th><th class="num">Comissão</th><th class="num">Gorjetas</th><th class="num">Direto</th><th class="num">Vales</th><th class="num">Pagamentos</th><th class="num">Saldo</th></tr></thead><tbody>${rows.length?rows.map(r=>{let p=(db.pros||[]).find(x=>x.id===r.professionalId);return `<tr><td>${escapeHtml(p?.name||r.professionalId||'—')}${p?.active===false?' <span class="v61-status off">inativa</span>':''}${r.uncertain?' <span class="v61-status warn">histórico parcial</span>':''}</td><td>${escapeHtml(reportUnitName(r.unitId))}</td><td class="num">${money(r.commission+r.remuneration)}</td><td class="num">${money(r.tips)}</td><td class="num">${money(r.direct)}</td><td class="num">${money(r.advances)}</td><td class="num">${money(r.payments)}</td><td class="num"><b>${money(r.balance)}</b></td></tr>`}).join(''):'<tr><td colspan="8"><div class="report-empty">Sem saldo profissional reconstruível no corte.</div></td></tr>'}</tbody></table></div></div>`}
 function v61AccountsTable(rows,f){return `<div class="report-card"><h3>Posição das contas</h3><div class="sub">Saldo inicial + movimentos a partir da data-base. PROCESSOR mostra bruto/taxa/líquido conhecido, sem afirmar liquidação bancária.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Conta</th><th>Tipo</th><th>Unidade</th><th class="num">Movimento no período</th><th class="num">Posição / líquido conhecido</th></tr></thead><tbody>${rows.length?rows.map(a=>`<tr><td><b>${escapeHtml(a.name)}</b>${a.inactiveCurrently?' <span class="v61-status off">inativa</span>':''}</td><td>${escapeHtml(financeAccountTypeLabel(a.type))}</td><td>${escapeHtml(reportUnitName(a.unitId))}</td><td class="num">${a.periodMovement===null?'—':money(a.periodMovement)}</td><td class="num">${!a.known?'<span class="v61-status warn">posição anterior à data-base</span>':a.type==='PROCESSOR'?`<b>${money(a.processorNetKnown)}</b><div class="v61-processor-note">bruto ${money(a.processorGross)} · taxa ${money(a.processorFees)} · a liquidar/sem confirmação externa</div>`:money(a.balanceAtCutoff)}</td></tr>`).join(''):'<tr><td colspan="5"><div class="report-empty">Nenhuma conta no filtro.</div></td></tr>'}</tbody></table></div></div>`}
 function v61ClientReceivableTable(rows){return `<div class="report-card"><h3>Contas a receber de clientes</h3><div class="sub">Conta Mensal/recebíveis de clientes. Não inclui cartão a liquidar.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Cliente</th><th>Comanda</th><th>Unidade econômica</th><th>Vencimento</th><th class="num">Original</th><th class="num">Em aberto</th></tr></thead><tbody>${rows.length?rows.slice(0,30).map(r=>`<tr><td>${escapeHtml(r.clientName||reportClient(r.clientId)?.name||'—')}</td><td>${escapeHtml(r.commandId||'—')}</td><td>${escapeHtml(reportUnitName(r.unitId))}</td><td>${r.dueDate?formatDateBR(r.dueDate):'—'}</td><td class="num">${money(r.originalAmount)}</td><td class="num"><b>${money(r.balanceAtCutoff)}</b></td></tr>`).join(''):'<tr><td colspan="6"><div class="report-empty">Sem recebíveis de clientes em aberto.</div></td></tr>'}</tbody></table></div></div>`}
