 function renderReportFinanceV61(s){let m=s.financeCurrent.finance,p=s.financePrevious.finance,d=s.financeCurrent.dre;return `<div class="report-section-head"><div><h2>Financeiro</h2><div class="muted">Tesouraria por caixa; DRE por competência. Unidade econômica e unidade financeira permanecem distintas.</div></div></div><div class="v60-fin-note"><b>Fluxo ≠ saldo ≠ competência:</b> suprimento e transferência alteram saldos sem virar receita. Conta Mensal mantém a receita na unidade do serviço; o recebimento fica na unidade/conta que recebeu.</div><div class="report-kpis">${reportKpi('Entradas brutas registradas',money(m.incoming),'Entradas efetivadas do ledger.',v60CompareMoney(m.incoming,p.incoming),'v60_fin_in')}${reportKpi('Saídas efetivadas',money(m.outgoing),'Saídas efetivadas do ledger.',v60CompareMoney(m.outgoing,p.outgoing),'v60_fin_out')}${reportKpi('Taxas registradas',money(m.fees),'Taxas congeladas nos recebimentos. ',v60CompareMoney(m.fees,p.fees),'v60_fin_fees')}${reportKpi('Movimento líquido após taxas',money(m.netAfterFees),'Entradas − saídas − taxas.',v60CompareMoney(m.netAfterFees,p.netAfterFees),'v60_fin_net')}${reportKpi('Conta Mensal a receber',money(m.clientReceivableBalance),'Somente recebíveis de clientes.','','v60_fin_receivables')}${reportKpi('Recebíveis de adquirentes',money(m.processorReceivableBalance),'Líquido conhecido; sem afirmar liquidação bancária.','','v61_processor_receivables')}${reportKpi('Contas a pagar',money(m.payableBalance),'Obrigações em aberto no corte.','','v60_fin_payables')}${reportKpi('Obrigações com profissionais',money(m.professionalBalance),'Posição; não gera novo custo na DRE.','','v61_prof_obligations')}</div><div class="v60-fin-grid"><div class="v60-fin-card"><h3>Conta Mensal no período</h3><div class="v60-fin-list"><div class="v60-fin-line"><span>Novos recebíveis</span><b>${money(m.generated.total)}</b></div><div class="v60-fin-line"><span>Recebimentos baixados</span><b>${money(m.collected.total)}</b></div><div class="v60-fin-line total"><span>Saldo em aberto</span><b>${money(m.clientReceivableBalance)}</b></div></div></div><div class="v60-fin-card"><h3>Fechamentos referentes ao período</h3><div class="sub">ReferenceDate operacional da sessão; não a data física do clique de fechamento.</div><div class="v60-fin-list"><div class="v60-fin-line"><span>Caixas de referência</span><b>${new Set(m.closures.map(x=>x.cashSessionId)).size}</b></div><div class="v60-fin-line"><span>Recebimentos consolidados</span><b>${money(m.closures.reduce((s,x)=>s+Number(x.amount||0),0))}</b></div></div></div></div>${typeof v60MethodsTable==='function'?v60MethodsTable(m.methods):''}<div class="v60-fin-grid">${v61ClientReceivableTable(m.clientReceivables)}${v61PayableTable(m.payables)}</div>${v61ProcessorTable(m.processorReceivables)}${v61ProfessionalsTable(m.professionalObligations)}${v61AccountsTable(m.accounts,m.f)}${typeof v60DreHtml==='function'?v60DreHtml(d):''}${typeof v60UnitsDreTable==='function'?v60UnitsDreTable(s.financeCurrent.units):''}`}

