 const _v61OverviewBase=renderReportOverview;renderReportOverview=function(s){let base=_v61OverviewBase(s),m=s.financeCurrent?.finance,d=s.financeCurrent?.dre,p=s.financePrevious?.finance,pd=s.financePrevious?.dre;if(!m||!d)return base;return `${base}<div class="report-section-head"><div><h2>Financeiro & DRE · estabilizado</h2><div class="muted">Movimento líquido já desconta taxas; Conta Mensal e adquirentes aparecem separados.</div></div></div><div class="report-kpis">${reportKpi('Movimento líquido após taxas',money(m.netAfterFees),'Entradas − saídas − taxas.',v60CompareMoney(m.netAfterFees,p?.netAfterFees),'v60_fin_net')}${reportKpi('Conta Mensal a receber',money(m.clientReceivableBalance),'Recebíveis econômicos de clientes.','','v60_fin_receivables')}${reportKpi('Receita líquida comercial',money(d.netRevenue),'Competência econômica.',v60CompareMoney(d.netRevenue,pd?.netRevenue),'v60_dre_revenue')}${reportKpi('Resultado Gerencial Parcial',money(d.resultPartial),'Sem inventar impostos/custos ausentes.',v60CompareMoney(d.resultPartial,pd?.resultPartial),'v60_dre_result')}</div>`};
 renderReports=function(){subbar.textContent='Relatórios gerenciais · V61 Financeiro + DRE estabilizado';let s=reportBuildState();window.v50ReportCache=s;window.v51ReportCache=s;window.v52ReportCache=s;window.v59ReportCache=s;window.v60ReportCache=s;window.v61ReportCache=s;let content=reportsTab==='overview'?renderReportOverview(s):reportsTab==='clients'?renderReportClients(s):reportsTab==='retention'?renderReportRetention(s):reportsTab==='agenda'?renderReportAgendaV52(s):reportsTab==='pros'?renderReportProfessionalsV52(s):reportsTab==='services'?renderReportServicesV59(s):reportsTab==='stock'?renderReportStockV59(s):reportsTab==='finance'?renderReportFinanceV61(s):renderReportComing(reportsTab);adminPage.innerHTML=`<div class="page-head"><div><h1>Relatórios</h1><div class="muted">Indicadores rastreáveis a partir das operações do sistema</div></div><div class="spacer"></div><span class="pill">V61 · Estabilização Financeiro + DRE</span></div><div class="report-shell">${reportNavHtml()}${reportFilterHtml()}${content}</div>`};window.renderReports=renderReports;
