 function v61Migrate(){let changed=false;db.migrationHistory=Array.isArray(db.migrationHistory)?db.migrationHistory:[];for(const a of (db.financialAccounts||[])){if(!Array.isArray(a.previousNames)){a.previousNames=[];changed=true}if(a.openingBalance!==undefined)a.openingBalance=rm(a.openingBalance)}for(const m of (db.demoCashMovements||[])){let a=(db.financialAccounts||[]).find(x=>x.id===(m.financialAccountId||m.accountId));if(a?.type==='PROCESSOR'&&!m.settlementReliability){m.settlementReliability='unknown';changed=true}}for(const e of (db.demoFinancialEntries||[])){if(e.sourceType==='stock_purchase'&&!e.obligationDate){e.obligationDate=e.originalDate||e.date||'';e.obligationDateReliability=e.originalDate?'legacy_originalDate':'legacy_date';changed=true}if(e.dueDate===undefined)e.dueDate=''}for(const p of (db.stockPurchases||[])){if(p.payableEntryId){let e=(db.demoFinancialEntries||[]).find(x=>x.id===p.payableEntryId);if(e){if(!e.obligationDate&&p.date){e.obligationDate=p.date;e.obligationDateReliability='explicit_purchase_date';changed=true}if(p.dueDate&&!e.dueDate){e.dueDate=p.dueDate;changed=true}}}}if(!db.migrationHistory.some(x=>x?.id===MIGRATION_ID)){db.migrationHistory.push({id:MIGRATION_ID,version:V61_SCHEMA,status:'applied',appliedAt:new Date().toISOString(),note:'Saldo inicial, espelho físico deduplicado, transferências pareadas, snapshots de adquirente, datas de obrigações, histórico de inativos e obrigações profissionais.'});changed=true}if(Number(db.schemaVersion||0)<V61_SCHEMA){db.schemaVersion=V61_SCHEMA;db.schemaMigratedAt=new Date().toISOString();changed=true}if(changed)save({render:false})}
 v61Migrate();
