 function v62VisitRevenue(v,f,data){let dimensional=f.professional!=='all'||f.category!=='all'||f.service!=='all';if(!dimensional)return Number(v?.revenue||0);return (data.serviceFacts||[]).filter(s=>s.visitKey===v?.key&&v62DimensionServiceMatch(s,f)).reduce((sum,s)=>sum+Number(s.revenue||0),0)}
