 function v62RegisteredClients(data,f){return (db.clients||[]).filter(c=>{let d=v62ClientCreatedDate(c);return d&&d>=f.from&&d<=f.to&&v62RegistrationMatches(c,f)})}
 function v62ConversionRows(data,f,registered){return registered.map(c=>{let first=v62FirstVisit(data,c.id);return {client:c,first,converted:!!(first&&first.date<=f.to),attribution:v62Attribution(c)}})}
