 function v62Quality(clients){let ids=[...new Set((clients||[]).map(c=>c?.client?.id||c?.id).filter(Boolean))],rows=ids.map(id=>reportClient(id)).filter(Boolean),missingSource=rows.filter(c=>!String(v62Attribution(c).source||'').trim()).length,missingOrigin=rows.filter(c=>!String(v62Attribution(c).origin||'').trim()).length,complete=rows.filter(c=>String(v62Attribution(c).source||'').trim()&&String(v62Attribution(c).origin||'').trim()).length;return {total:rows.length,missingSource,missingOrigin,complete,completePct:rows.length?v62Pct(complete,rows.length):0}}
 function v62Reliability(clients){let ids=[...new Set((clients||[]).map(c=>c?.client?.id||c?.id).filter(Boolean))],out={reliable:0,legacy:0,fallback:0};for(const id of ids){let r=v62Attribution(reportClient(id)).historicalReliability;if(r==='reliable')out.reliable++;else if(r==='legacy_current_profile')out.legacy++;else out.fallback++}return out}
 function v62GroupFirst(data,f,acquired,registered,key){let labels=new Set();registered.forEach(c=>labels.add(v62Label(v62Attribution(c)[key])));acquired.forEach(r=>labels.add(v62Label(r.attribution[key])));let rows=[];for(const label of labels){let regs=registered.filter(c=>v62Label(v62Attribution(c)[key])===label),acs=acquired.filter(r=>v62Label(r.attribution[key])===label),converted=regs.filter(c=>{let first=v62FirstVisit(data,c.id);return first&&first.date<=f.to}).length,rev=v62Rm(acs.reduce((s,r)=>s+r.revenue,0)),paid=acs.filter(r=>r.revenue>0).length,ret=acs.filter(r=>!!v62NextVisit(data,r.first,f.to,f)).length,lifetime=v62Rm(acs.reduce((s,r)=>s+v62ClientLifetimeRevenue(data,r.client.id,f.to,f),0));rows.push({label,registrations:regs.length,acquired:acs.length,converted,conversion:regs.length?v62Pct(converted,regs.length):null,revenue:rev,ticket:paid?rev/paid:null,returned:ret,retention:acs.length?v62Pct(ret,acs.length):null,lifetime})}return rows.sort((a,b)=>b.acquired-a.acquired||b.revenue-a.revenue||a.label.localeCompare(b.label,'pt-BR'))}
 function v62GroupPost(data,f,post,key,acquired=[]){let labels=new Set(),m=new Map();for(const a of acquired)labels.add(v62Label(a.attribution[key]));for(const v of post){let label=v62Label(v.attribution[key]);labels.add(label);let r=m.get(label)||{label,clientIds:new Set(),visits:0,revenue:0,paid:0,lifetimeIds:new Set()};r.clientIds.add(v.clientId);r.visits++;r.revenue+=v.revenue;if(v.revenue>0)r.paid++;r.lifetimeIds.add(v.clientId);m.set(label,r)}return [...labels].map(label=>{let r=m.get(label)||{label,clientIds:new Set(),visits:0,revenue:0,paid:0,lifetimeIds:new Set()},cohort=acquired.filter(a=>v62Label(a.attribution[key])===label).map(a=>a.client),ret=v62Retention30(data,cohort,f),lifetime=v62Rm([...r.lifetimeIds].reduce((s,id)=>s+v62ClientLifetimeRevenue(data,id,f.to,f),0));return {label:r.label,clients:r.clientIds.size,visits:r.visits,revenue:v62Rm(r.revenue),ticket:r.paid?r.revenue/r.paid:null,frequency:r.clientIds.size?r.visits/r.clientIds.size:0,valuePerClient:r.clientIds.size?r.revenue/r.clientIds.size:0,lifetime,retention30:ret.rate,mature30:ret.matureIds.length}}).sort((a,b)=>b.revenue-a.revenue||b.clients-a.clients||a.label.localeCompare(b.label,'pt-BR'))}
 function v62FirstServiceRows(data,acquired){let m=new Map();for(const r of acquired){for(const s of (data.serviceFacts||[]).filter(x=>x.visitKey===r.first.key)){let k=s.serviceId||`name:${s.serviceName}`,x=m.get(k)||{label:s.serviceName||'Serviço',qty:0,revenue:0};x.qty+=1;x.revenue+=Number(s.revenue||0);m.set(k,x)}}return [...m.values()].map(x=>({...x,revenue:v62Rm(x.revenue)})).sort((a,b)=>b.qty-a.qty||b.revenue-a.revenue)}
 function v62AcquisitionUnits(acquired){let m=new Map();for(const r of acquired){let id=r.first.unitId||'',x=m.get(id)||{unitId:id,label:reportUnitName(id),clients:0,revenue:0};x.clients++;x.revenue+=r.revenue;m.set(id,x)}return [...m.values()].map(x=>({...x,revenue:v62Rm(x.revenue)})).sort((a,b)=>b.clients-a.clients||b.revenue-a.revenue)}
