  v62EnsureMarketingAttributionSnapshots(data,{persist:true});let registered=v62RegisteredClients(data,f),conversionRows=v62ConversionRows(data,f,registered),acquired=v62AcquiredClients(data,f),post=v62SubsequentVisits(data,f),postClientIds=[...new Set(post.map(v=>v.clientId))],postClients=postClientIds.map(id=>reportClient(id)).filter(Boolean),firstRevenue=v62Rm(acquired.reduce((s,r)=>s+r.revenue,0)),paidFirst=acquired.filter(r=>r.revenue>0).length,converted=conversionRows.filter(x=>x.converted).length,returnedAcquired=acquired.filter(r=>!!v62NextVisit(data,r.first,f.to,f)).length,postRevenue=v62Rm(post.reduce((s,v)=>s+v.revenue,0)),postPaid=post.filter(v=>v.revenue>0).length,postLifetime=v62Rm(postClientIds.reduce((s,id)=>s+v62ClientLifetimeRevenue(data,id,f.to,f),0)),ret30=v62Retention30(data,acquired.map(x=>x.client),f),quality=v62Quality([...registered,...acquired]),reliability=v62Reliability([...registered,...acquired,...postClients]);
  return {f,registered,conversionRows,acquired,post,postClients,quality,reliability,first:{registrations:registered.length,converted,conversion:registered.length?v62Pct(converted,registered.length):null,clients:acquired.length,revenue:firstRevenue,ticket:paidFirst?firstRevenue/paidFirst:null,returned:returnedAcquired,retention:acquired.length?v62Pct(returnedAcquired,acquired.length):null,source:v62GroupFirst(data,f,acquired,registered,'source'),origin:v62GroupFirst(data,f,acquired,registered,'origin'),services:v62FirstServiceRows(data,acquired),units:v62AcquisitionUnits(acquired)},postMetrics:{clients:postClientIds.length,visits:post.length,revenue:postRevenue,ticket:postPaid?postRevenue/postPaid:null,frequency:postClientIds.length?post.length/postClientIds.length:0,valuePerClient:postClientIds.length?postRevenue/postClientIds.length:0,lifetime:postLifetime,lifetimePerClient:postClientIds.length?postLifetime/postClientIds.length:0,retention30:ret30.rate,mature30:ret30.matureIds.length,source:v62GroupPost(data,f,post,'source',acquired),origin:v62GroupPost(data,f,post,'origin',acquired)}}
