 function v62PctOrDash(v){return v===null||v===undefined?'—':reportPctText(v)}
 function v62MoneyOrDash(v){return v===null||v===undefined?'—':money(v)}
 function v62FirstGroupTable(rows,title){return `<div class="report-card"><h3>${escapeHtml(title)}</h3><div class="sub">Cadastro e primeira visita permanecem conceitos separados. Conversão = cadastros do período que já fizeram a primeira visita até a data final.</div><div class="report-table-wrap"><table class="report-table v62-marketing-table"><thead><tr><th>Canal</th><th class="num">Cadastros</th><th class="num">1ª visita</th><th class="num">Conversão</th><th class="num">Receita 1ª visita</th><th class="num">Ticket</th><th class="num">Retornaram</th><th class="num">Retenção*</th><th class="num">Acumulado**</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr class="clickable" onclick="openReportDrilldown('v62_first_group|${encodeURIComponent(title)}|${encodeURIComponent(r.label)}')"><td><b>${escapeHtml(r.label)}</b></td><td class="num">${r.registrations}</td><td class="num">${r.acquired}</td><td class="num">${v62PctOrDash(r.conversion)}</td><td class="num">${money(r.revenue)}</td><td class="num">${v62MoneyOrDash(r.ticket)}</td><td class="num">${r.returned}</td><td class="num">${v62PctOrDash(r.retention)}</td><td class="num">${money(r.lifetime)}</td></tr>`).join(''):'<tr><td colspan="9"><div class="report-empty">Sem dados para este recorte.</div></td></tr>'}</tbody></table></div><div class="report-definition">* Retenção desta tabela = clientes cuja primeira visita está no período e que já tiveram uma visita posterior até a data final. ** Acumulado = receita histórica até a data final para a coorte exibida; é secundário ao resultado do período.</div></div>`}
 function v62PostGroupTable(rows,title){return `<div class="report-card"><h3>${escapeHtml(title)}</h3><div class="sub">Somente visitas posteriores à primeira visita da vida da cliente que ocorreram dentro do período selecionado.</div><div class="report-table-wrap"><table class="report-table v62-marketing-table"><thead><tr><th>Canal</th><th class="num">Clientes</th><th class="num">Visitas</th><th class="num">Receita período</th><th class="num">Ticket</th><th class="num">Frequência</th><th class="num">Valor/cliente</th><th class="num">Retenção 30d</th><th class="num">Acumulado*</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr class="clickable" onclick="openReportDrilldown('v62_post_group|${encodeURIComponent(title)}|${encodeURIComponent(r.label)}')"><td><b>${escapeHtml(r.label)}</b></td><td class="num">${r.clients}</td><td class="num">${r.visits}</td><td class="num">${money(r.revenue)}</td><td class="num">${v62MoneyOrDash(r.ticket)}</td><td class="num">${reportNumber(r.frequency,2)}</td><td class="num">${money(r.valuePerClient)}</td><td class="num">${v62PctOrDash(r.retention30)}${r.retention30===null?'':`<div class="v62-secondary">${r.mature30} madura(s)</div>`}</td><td class="num">${money(r.lifetime)}</td></tr>`).join(''):'<tr><td colspan="9"><div class="report-empty">Sem visitas posteriores neste recorte.</div></td></tr>'}</tbody></table></div><div class="report-definition">* Acumulado = receita histórica até a data final das clientes que aparecem neste recorte. Retenção 30d só usa clientes com pelo menos 30 dias de observação; quando não há base madura, fica “—”.</div></div>`}
 function v62ServiceTable(rows){return `<div class="report-card"><h3>Serviços da primeira visita</h3><div class="sub">Serviços efetivamente presentes na primeira visita concluída da cliente.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Serviço</th><th class="num">Qtd.</th><th class="num">Receita atribuída</th></tr></thead><tbody>${rows.length?rows.slice(0,30).map(r=>`<tr><td><b>${escapeHtml(r.label)}</b></td><td class="num">${r.qty}</td><td class="num">${money(r.revenue)}</td></tr>`).join(''):'<tr><td colspan="3"><div class="report-empty">Sem serviços de primeira visita no período.</div></td></tr>'}</tbody></table></div></div>`}
 function v62UnitTable(rows){return `<div class="report-card"><h3>Aquisição por unidade</h3><div class="sub">Unidade da primeira visita, não a unidade em que o cadastro foi criado.</div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Unidade</th><th class="num">Clientes</th><th class="num">Receita 1ª visita</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td><b>${escapeHtml(r.label)}</b></td><td class="num">${r.clients}</td><td class="num">${money(r.revenue)}</td></tr>`).join(''):'<tr><td colspan="3"><div class="report-empty">Sem aquisições no período.</div></td></tr>'}</tbody></table></div></div>`}
 function v62QualityHtml(m){let q=m.quality,r=m.reliability;return `<div class="report-card"><h3>Qualidade da atribuição</h3><div class="sub">Campo vazio continua vazio no cadastro e aparece apenas como “Não especificado” no relatório.</div><div class="v62-quality-grid"><div class="v62-quality-item"><span>Base avaliada</span><b>${q.total}</b></div><div class="v62-quality-item"><span>Sem Como conheceu</span><b>${q.missingSource}</b></div><div class="v62-quality-item"><span>Sem origem</span><b>${q.missingOrigin}</b></div><div class="v62-quality-item"><span>Atribuição completa</span><b>${reportPctText(q.completePct)}</b></div></div><div class="report-definition" style="margin-top:10px"><span class="v62-source-tag reliable">${r.reliable} confiável</span> <span class="v62-source-tag legacy">${r.legacy} legado congelado</span> <span class="v62-source-tag fallback">${r.fallback} fallback atual</span><br>Dados importados de sistemas anteriores são aproveitados. Quando não existe snapshot original da primeira visita, o valor disponível no cadastro é congelado com confiabilidade histórica explicitamente limitada.</div></div>`}
 function v62MarketingTabs(){return `<div class="v62-marketing-tabs"><button class="${v62MarketingView==='first'?'active':''}" onclick="v62SetMarketingView('first')">Primeira visita</button><button class="${v62MarketingView==='post'?'active':''}" onclick="v62SetMarketingView('post')">Visitas posteriores</button></div>`}
 function renderReportMarketingV62(s){let m=s.marketingCurrent;if(!m)return '<div class="report-empty">Marketing indisponível.</div>';let first=m.first,post=m.postMetrics,body=v62MarketingView==='first'?`<div class="report-section-head"><div><h2>Marketing · Primeira visita</h2><div class="muted">Aquisição real: cadastro, primeira visita concluída, receita da estreia e retorno posterior.</div></div></div><div class="report-kpis">${reportKpi('Clientes conquistadas',first.clients,'Primeira visita concluída da vida ocorreu no período.','','v62_first_clients')}${reportKpi('Cadastros no período',first.registrations,'Usa a data real de cadastro quando disponível.','','v62_registrations')}${reportKpi('Conversão cadastro → 1ª visita',v62PctOrDash(first.conversion),'Cadastros do período que já fizeram a primeira visita até a data final.','','v62_conversion')}${reportKpi('Receita da 1ª visita',money(first.revenue),'Receita comercial atribuída à primeira visita.','','v62_first_revenue')}${reportKpi('Ticket da 1ª visita',v62MoneyOrDash(first.ticket),'Receita das primeiras visitas com valor reconhecido.','','v62_first_revenue')}${reportKpi('Retornaram após a estreia',first.returned,'Clientes da coorte que já fizeram visita posterior até a data final.','','v62_first_returned')}</div><div class="report-grid-2">${v62FirstGroupTable(first.source,'Como conheceu')}${v62FirstGroupTable(first.origin,'Origem do cadastro')}</div><div class="report-grid-2">${v62ServiceTable(first.services)}${v62UnitTable(first.units)}</div>`:`<div class="report-section-head"><div><h2>Marketing · Visitas posteriores</h2><div class="muted">Recorrência e faturamento gerados depois da primeira visita, dentro do período selecionado.</div></div></div><div class="report-kpis">${reportKpi('Clientes recorrentes no período',post.clients,'Clientes com ao menos uma visita posterior à primeira no recorte.','','v62_post_clients')}${reportKpi('Visitas posteriores',post.visits,'Quantidade de atendimentos posteriores no período.','','v62_post_visits')}${reportKpi('Receita pós-1ª visita',money(post.revenue),'Faturamento das visitas posteriores dentro do período.','','v62_post_revenue')}${reportKpi('Ticket pós-1ª visita',v62MoneyOrDash(post.ticket),'Receita posterior ÷ visitas posteriores com valor reconhecido.','','v62_post_revenue')}${reportKpi('Frequência no período',reportNumber(post.frequency,2),'Visitas posteriores ÷ clientes recorrentes do período.','','v62_post_visits')}${reportKpi('Valor por cliente',money(post.valuePerClient),'Receita posterior do período ÷ clientes recorrentes.','','v62_post_revenue')}${reportKpi('Retenção 30 dias',v62PctOrDash(post.retention30),post.retention30===null?'Sem coorte madura suficiente.':`${post.mature30} cliente(s) com 30 dias de observação.`,'','v62_retention30')}${reportKpi('Faturamento acumulado',money(post.lifetime),'Indicador secundário: histórico até a data final das clientes recorrentes deste recorte.','','v62_post_lifetime')}</div><div class="report-grid-2">${v62PostGroupTable(post.source,'Como conheceu')}${v62PostGroupTable(post.origin,'Origem do cadastro')}</div>`;return `${v62MarketingTabs()}<div class="v62-marketing-note"><b>Origem do cadastro ≠ Como conheceu.</b> Origem é o canal em que o cadastro entrou (Presencial, WhatsApp, Site etc.); “Como conheceu” é a atribuição de descoberta (Instagram, Google, Indicação, IA etc.). Os relatórios mantêm os conceitos separados.</div>${body}${v62QualityHtml(m)}<div class="v62-marketing-note"><b>CAC, ROAS, custo por lead e ROI de campanha:</b> Dados de investimento ainda não disponíveis. Nenhum desses indicadores é estimado ou inventado nesta versão.</div>`}
